1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import { serverRootPassword } from "../lib/sftp";
4	import { GAME_FAMILIES, type GameFamily } from "../lib/games";
5	import {
6	  judgeGameUpdate,
7	  parseGameUpdateOutput,
8	  updateCommand,
9	  updatesFromSteam,
10	} from "../lib/game-update-verify";
11	import { execFile } from "node:child_process";
12	import { promisify } from "node:util";
13	import type { Job } from "@prisma/client";
14	
15	const execFileP = promisify(execFile);
16	
17	/**
18	 * Game-server auto-update handlers.
19	 *
20	 * `gameUpdate` runs the per-family update over SSH against the server's private
21	 * IP (the worker can reach vmbr1) and PROVES the outcome before saying anything
22	 * to the customer. `gameUpdateSweep` finds RUNNING game servers with
23	 * `autoUpdate=true` and enqueues GAME_UPDATE jobs for them — safe to call
24	 * periodically (it de-dupes on in-flight jobs).
25	 *
26	 * The remote command used to end `; true` with every step `|| true`, so it could
27	 * not exit non-zero and this handler always fired *"The latest server update was
28	 * applied and the service was restarted."* — unattended, every 6 hours, whether
29	 * or not steamcmd existed, a unit matched, or the service came back. The command
30	 * builder, the output parser and the verdict now live in lib/game-update-verify.ts
31	 * where they are tested; SSH failure is still a failure, but a clean SSH exit is
32	 * no longer evidence of anything.
33	 *
34	 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire these
35	 * in there (`GAME_UPDATE: gameUpdate`) and call `gameUpdateSweep()` on a timer.
36	 */
37	
38	async function loadGameServer(serverId: string) {
39	  const server = await db.server.findUnique({
40	    where: { id: serverId },
41	    include: { osTemplate: true },
42	  });
43	  if (!server) throw new Error(`Server ${serverId} not found`);
44	  return server;
45	}
46	
47	async function notify(userId: string, title: string, body?: string, href?: string) {
48	  try {
49	    await db.notification.create({ data: { userId, title, body, href } });
50	  } catch (e) {
51	    console.error("[game-update] notify failed", e);
52	  }
53	}
54	
55	/**
56	 * Tell the customer once, not once per retry.
57	 *
58	 * The worker retries a failed job three times, and this one runs every six
59	 * hours; without this, a server whose steamcmd is missing would generate three
60	 * identical alarms per sweep, forever, and the customer would learn to ignore
61	 * them — which is the same outcome as not telling them.
62	 */
63	async function notifyFailureOnce(userId: string, serverId: string, title: string, body: string, href: string) {
64	  const since = new Date(Date.now() - 24 * 60 * 60_000);
65	  const dupe = await db.notification
66	    .findFirst({ where: { userId, title, createdAt: { gt: since } } })
67	    .catch(() => null);
68	  if (dupe) {
69	    console.error(`[game-update] ${serverId}: ${body} (customer already notified in the last 24h)`);
70	    return;
71	  }
72	  await notify(userId, title, body, href);
73	}
74	
75	/** Run the per-family update over SSH and verify the result. */
76	export async function gameUpdate(job: Job): Promise<void> {
77	  const server = await loadGameServer(job.serverId!);
78	  if (SANDBOX) {
79	    // No VM exists, so nothing can be proven. Say that, rather than simulating a
80	    // success message the production path is no longer willing to send.
81	    await notify(
82	      server.userId,
83	      `${server.osTemplate.name} auto-update simulated on ${server.hostname} (sandbox)`,
84	      "Sandbox only — no server was contacted, nothing was updated and nothing was restarted.",
85	      `/dashboard/servers/${server.id}`
86	    );
87	    return;
88	  }
89	  const family = server.osTemplate.family as GameFamily;
90	  if (!GAME_FAMILIES.includes(family)) {
91	    throw new Error(`game update: ${server.hostname} is not a game server`);
92	  }
93	  if (server.status !== "RUNNING") throw new Error("game update: server is not running");
94	  const password = serverRootPassword(server);
95	  if (!server.ipAddress || !password) {
96	    throw new Error("game update: server has no IP/password yet");
97	  }
98	  const scrub = (s: string): string => (password ? s.split(password).join("***") : s);
99	  const href = `/dashboard/servers/${server.id}`;
100	
101	  const remote = updateCommand(family);
102	  let stdout = "";
103	  try {
104	    const r = await execFileP(
105	      "sshpass",
106	      [
107	        "-p",
108	        password,
109	        "ssh",
110	        "-o",
111	        "StrictHostKeyChecking=no",
112	        "-o",
113	        "UserKnownHostsFile=/dev/null",
114	        "-o",
115	        "ConnectTimeout=15",
116	        `root@${server.ipAddress}`,
117	        remote,
118	      ],
119	      { timeout: 600_000, maxBuffer: 4 * 1024 * 1024 }
120	    );
121	    stdout = String(r.stdout ?? "");
122	  } catch (e: any) {
123	    // A non-zero exit is now possible and meaningful, but the markers may still
124	    // have been printed before whatever went wrong — keep them and let the
125	    // verdict decide, rather than discarding evidence.
126	    stdout = String(e?.stdout ?? "");
127	    if (!/^NXGU:END$/m.test(stdout)) {
128	      // execFile embeds the full argv — including `-p <rootPassword>` — into its
129	      // error message/cmd. Rethrow a sanitized error so the password can never be
130	      // stored in Job.error (the worker also redacts as a second line of defense).
131	      const detail = scrub(String(e?.stderr || e?.message || e));
132	      const reason = `game update failed: ${detail}`;
133	      await notifyFailureOnce(
134	        server.userId,
135	        server.id,
136	        `${server.osTemplate.name} auto-update FAILED on ${server.hostname}`,
137	        `We could not reach or run the update on your server, so nothing was updated: ${detail.slice(0, 300)}`,
138	        href
139	      );
140	      throw new Error(reason);
141	    }
142	  }
143	
144	  const facts = parseGameUpdateOutput(scrub(stdout));
145	  const verdict = judgeGameUpdate({ family, hostname: server.hostname, facts });
146	
147	  if (!verdict.ok) {
148	    await notifyFailureOnce(
149	      server.userId,
150	      server.id,
151	      `${server.osTemplate.name} auto-update did not complete on ${server.hostname}`,
152	      verdict.reason,
153	      href
154	    );
155	    // Failing the job is the point: it puts the reason in Job.error and in the
156	    // admin job list instead of leaving a green tick over a dead server.
157	    throw new Error(`game update not verified: ${verdict.reason}`);
158	  }
159	
160	  await notify(server.userId, verdict.title, verdict.body, href);
161	}
162	
163	/**
164	 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
165	 * auto-update and has no job already in flight. Idempotent / safe to call on a
166	 * timer. Returns nothing; logs a summary.
167	 */
168	export async function gameUpdateSweep(): Promise<void> {
169	  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
170	  const candidates = await db.server.findMany({
171	    where: {
172	      status: "RUNNING",
173	      autoUpdate: true,
174	      osTemplate: { family: { in: [...GAME_FAMILIES] } },
175	    },
176	    select: { id: true, hostname: true, osTemplate: { select: { family: true } } },
177	  });
178	  if (candidates.length === 0) return;
179	
180	  let enqueued = 0;
181	  for (const s of candidates) {
182	    const inflight = await db.job.count({
183	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
184	    });
185	    if (inflight > 0) continue;
186	    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
187	    enqueued++;
188	  }
189	  if (enqueued > 0) {
190	    const restartOnly = candidates.filter((s) => !updatesFromSteam(s.osTemplate.family as GameFamily)).length;
191	    console.log(
192	      `[game-update] sweep enqueued ${enqueued} job(s)` +
193	        (restartOnly > 0 ? ` (${restartOnly} candidate(s) are restart-only families with no update source)` : "")
194	    );
195	  }
196	}
