1	/**
2	 * SSL verification rules — the pure decision logic behind "this certificate is
3	 * active" and "this certificate was renewed".
4	 *
5	 * Two incidents from the 2026-07-26 rehearsal's M7 list live here.
6	 *
7	 * M7 #6 — *"SSL certificate renewed for example.com — Verified live … valid
8	 * until <old date>"*. `certbot certonly` exits 0 and prints "Certificate not yet
9	 * due for renewal" when it does NOTHING, and that string was in the same
10	 * success-marker alternation as "Congratulations". The unchanged expiry was then
11	 * read back off disk and reported as a renewal. Nothing had been renewed.
12	 * `classifyCertbotOutcome` separates the two, because an exit code is not proof.
13	 *
14	 * M7 #5 — the served-certificate probe checked only name-match and a future
15	 * `notAfter`. Behind a CDN that terminates TLS at its edge (Cloudflare, Fastly),
16	 * the probe captures the EDGE certificate — which is valid, publicly trusted and
17	 * covers the domain — and the sweep then overwrote `expiresAt` with the edge's
18	 * date. The origin's real certificate was therefore never seen to be expiring,
19	 * never renewed, and died silently. `servedCertVerdict` refuses to adopt an
20	 * expiry from a certificate it can positively see is not ours, and it stops
21	 * treating an untrusted certificate as ACTIVE.
22	 *
23	 * The discriminator is the ISSUER, deliberately, and only in one direction: a
24	 * later `notAfter` from OUR issuer is certbot's own systemd timer renewing
25	 * out-of-band, which we want to keep picking up. A certificate from someone
26	 * else's issuer is not ours to reason about, so we keep our own record and say
27	 * why. Where the issuer cannot be judged we adopt nothing and invent nothing.
28	 *
29	 * Deterministic: no TLS, no SSH, no clock. Covered by test/ssl-verify.test.ts.
30	 */
31	
32	// ---------------------------------------------------------------------------
33	// Did certbot actually issue anything?
34	// ---------------------------------------------------------------------------
35	
36	export type CertbotOutcome =
37	  | { kind: "issued"; detail: string }
38	  | { kind: "unchanged"; detail: string }
39	  | { kind: "failed"; detail: string };
40	
41	/** certbot printed one of these only when it really obtained a certificate. */
42	const ISSUED_MARKERS = /Congratulations|Successfully received certificate|Certificate is saved/i;
43	/** certbot printed this when it decided there was nothing to do. */
44	const UNCHANGED_MARKERS = /not yet due for renewal|Certificate not yet due|keeping the existing certificate/i;
45	
46	/**
47	 * Classify a certbot run. The exit code alone is worthless here: certbot exits 0
48	 * both when it issues and when it declines to.
49	 *
50	 * `code` is `number | null` because ssh2 reports null when the channel closed
51	 * without an exit status. That is "we do not know", which is not success — the
52	 * whole point of this module is that an unknown outcome is never upgraded.
53	 */
54	export function classifyCertbotOutcome(code: number | null, output: string): CertbotOutcome {
55	  const text = String(output ?? "");
56	  const detail = text.trim().slice(0, 400);
57	  if (code !== 0) return { kind: "failed", detail };
58	  // Order matters: a forced renewal prints BOTH strings, and in that case a
59	  // certificate really was issued.
60	  if (ISSUED_MARKERS.test(text)) return { kind: "issued", detail };
61	  if (UNCHANGED_MARKERS.test(text)) return { kind: "unchanged", detail };
62	  return { kind: "failed", detail };
63	}
64	
65	// ---------------------------------------------------------------------------
66	// Whose certificate is on the wire?
67	// ---------------------------------------------------------------------------
68	
69	/** What the TLS handshake told us about the certificate being served. */
70	export type ServedIdentity = {
71	  notAfter: Date;
72	  coversDomain: boolean;
73	  /** Issuer common name, e.g. "R11", "E5", "WE1". "" when unreadable. */
74	  issuerCN: string;
75	  /** Issuer organisation, e.g. "Let's Encrypt", "Google Trust Services". "" when unreadable. */
76	  issuerO: string;
77	  /** `socket.authorized` — would a browser trust this chain? */
78	  authorized: boolean;
79	  /** `socket.authorizationError`, "" when authorized. */
80	  authorizationError: string;
81	};
82	
83	/**
84	 * Is the certificate on the wire plausibly from the issuer we use for this row?
85	 *
86	 * Returns true when we cannot tell. A false mismatch is as misleading as a
87	 * missed one (the same reasoning as `majorVersion` in worker/migrate-real.ts):
88	 * refusing to adopt an expiry we have no grounds to doubt would strand rows on
89	 * stale dates, which is the very failure this is meant to prevent.
90	 */
91	export function issuerMatchesOurs(
92	  served: Pick<ServedIdentity, "issuerCN" | "issuerO">,
93	  ourIssuer: string
94	): boolean {
95	  const cn = String(served.issuerCN ?? "").trim();
96	  const o = String(served.issuerO ?? "").trim();
97	  if (!cn && !o) return true; // nothing to judge
98	  if (String(ourIssuer ?? "").toLowerCase() !== "letsencrypt") return true; // we only know LE
99	
100	  if (/let'?s encrypt/i.test(o) || /let'?s encrypt/i.test(cn)) return true;
101	  // Let's Encrypt's intermediates are a single letter plus digits: R3, R10, R11,
102	  // E1, E5… Matching the shape as well as the name keeps this working when they
103	  // rotate to a name we have not seen.
104	  if (/^[RE]\d{1,3}$/.test(cn)) return true;
105	  // The staging hierarchy, so a staging certificate is not mistaken for a CDN's.
106	  if (/\(STAGING\)/i.test(o) || /\(STAGING\)/i.test(cn)) return true;
107	  return false;
108	}
109	
110	export type ServedVerdict = {
111	  /** What the row's status should become. `null` = leave it as it is. */
112	  status: "ACTIVE" | "EXPIRED" | null;
113	  /** May we overwrite the row's `expiresAt` from what we saw on the wire? */
114	  adoptExpiry: boolean;
115	  /** Customer-facing explanation, or null when there is nothing to say. */
116	  note: string | null;
117	};
118	
119	const DAY_MS = 86_400_000;
120	
121	/**
122	 * Decide what a served certificate proves about our row.
123	 *
124	 * Ordered by what the customer loses: a chain a browser will reject outranks a
125	 * date we might have adopted from the wrong certificate, which outranks an
126	 * ordinary expiry.
127	 */
128	export function servedCertVerdict(opts: {
129	  domain: string;
130	  served: ServedIdentity;
131	  /** The expiry we last observed for OUR certificate. */
132	  recordedExpiry: Date | null;
133	  /** The row's `issuer` column. */
134	  ourIssuer: string;
135	  now: number;
136	}): ServedVerdict {
137	  const { domain, served, recordedExpiry, now } = opts;
138	
139	  if (!served.coversDomain) {
140	    return {
141	      status: null,
142	      adoptExpiry: false,
143	      note:
144	        `Port 443 on ${domain} is serving a certificate issued for a different hostname, so visitors get ` +
145	        `NET::ERR_CERT_COMMON_NAME_INVALID. Check which certificate your web server is configured to use.`,
146	    };
147	  }
148	
149	  const expiredOnWire = served.notAfter.getTime() <= now;
150	
151	  if (!served.authorized && !expiredOnWire) {
152	    // A self-signed or broken-chain certificate covering the right name used to
153	    // read as ACTIVE, because only the name and the date were checked. Every
154	    // visitor sees a full-page browser warning.
155	    return {
156	      status: null,
157	      adoptExpiry: false,
158	      note:
159	        `The certificate served for ${domain} covers the right hostname but is NOT trusted by browsers ` +
160	        `(${served.authorizationError || "chain verification failed"}), so visitors still get a security ` +
161	        `warning. This is not an active certificate. Check that your web server is serving the full chain ` +
162	        `(fullchain.pem, not cert.pem).`,
163	    };
164	  }
165	
166	  const ours = issuerMatchesOurs(served, opts.ourIssuer);
167	  const differentDate =
168	    recordedExpiry !== null && Math.abs(served.notAfter.getTime() - recordedExpiry.getTime()) > DAY_MS;
169	
170	  if (!ours && differentDate) {
171	    // The M7 #5 case. Adopting this date is what let the origin certificate die.
172	    const oursValid = recordedExpiry !== null && recordedExpiry.getTime() > now;
173	    const issuer = served.issuerO || served.issuerCN || "an unknown issuer";
174	    return {
175	      status: oursValid ? "ACTIVE" : "EXPIRED",
176	      adoptExpiry: false,
177	      note:
178	        `The certificate served for ${domain} was issued by ${issuer} and expires ` +
179	        `${served.notAfter.toISOString().slice(0, 10)} — it is NOT the certificate we issued, which expires ` +
180	        `${recordedExpiry!.toISOString().slice(0, 10)}. That normally means ${domain} is behind a CDN or ` +
181	        `proxy (Cloudflare, Fastly) terminating TLS at its edge. We are keeping our own expiry date rather ` +
182	        `than the edge's, because yours is the one that has to be renewed — if it lapses, the CDN can no ` +
183	        `longer reach your origin over HTTPS.`,
184	    };
185	  }
186	
187	  if (expiredOnWire) {
188	    return {
189	      status: "EXPIRED",
190	      adoptExpiry: ours,
191	      note:
192	        `The certificate being served for ${domain} expired on ${served.notAfter.toISOString().slice(0, 10)}. ` +
193	        `Visitors see a browser security warning until a new one is installed.`,
194	    };
195	  }
196	
197	  return { status: "ACTIVE", adoptExpiry: ours, note: null };
198	}
199	
200	/**
201	 * The sentence for a renewal that renewed nothing.
202	 *
203	 * Split out and tested because getting it wrong is the whole defect: the old
204	 * message said "renewed … valid until <the same date as before>", which reads as
205	 * a successful renewal and is exactly why nobody noticed.
206	 */
207	export function unchangedRenewalNote(domain: string, expiresAt: Date, isRenewal: boolean): string {
208	  const when = expiresAt.toISOString().slice(0, 10);
209	  return isRenewal
210	    ? `certbot did not issue a new certificate for ${domain} — it reported the existing one is not yet due ` +
211	        `for renewal and left it in place, valid until ${when}. Nothing changed. If you believe it IS due, ` +
212	        `the certificate on disk disagrees with our record and support should force a renewal.`
213	    : `A certificate for ${domain} already existed and certbot reused it rather than requesting a new one. ` +
214	        `It is valid until ${when}.`;
215	}
