1	import type { Client } from "ssh2";
2	import { exec, assertDomain, assert, shellQuote, SETUP_TIMEOUT_MS } from "./ssh-exec";
3	
4	/**
5	 * Shared HTTP verification for things we claim are "serving".
6	 *
7	 * Lifted verbatim out of worker/apps.ts, which is the file that got this right
8	 * first and is named in docs/QA-JOURNEY.md as the model. It lived there as two
9	 * private functions, so worker/websites.ts marked a site ACTIVE with the message
10	 * "Your nginx site is configured and serving" having made no request of any kind
11	 * (M7 #4) — and that unverified ACTIVE then gated the SSL flow, so certbot
12	 * HTTP-01 was offered for a vhost that might not answer at all.
13	 *
14	 * The rule this module exists to enforce: an install/config step that exited 0
15	 * is not evidence that anything is being served. Only a response is.
16	 */
17	
18	export type Probe = {
19	  /** Path on the app's own domain. */
20	  path: string;
21	  /** Accepted status codes (default: 200 only). */
22	  codes?: string[];
23	  /** Every pattern must be present in the body. */
24	  require: RegExp[];
25	  /** No pattern may be present (application-level error pages). */
26	  reject?: RegExp[];
27	  /** What passing this probe proves — quoted verbatim in failures. */
28	  proves: string;
29	};
30	
31	
32	/**
33	 * Fetch one path on the app's own domain FROM INSIDE the VM, with the hostname
34	 * pinned to 127.0.0.1 (`curl --resolve`). That sends the real Host header, so it
35	 * genuinely tests "does this vhost serve this application" while remaining
36	 * correct before the customer's DNS has propagated. Mirrors the probe in
37	 * worker/migrate-real.ts, which exists because a port check proved only that
38	 * something was listening while sites returned 502s.
39	 */
40	export async function httpProbe(conn: Client, domain: string, path: string): Promise<{ code: string; body: string }> {
41	  assertDomain(domain);
42	  assert(/^\/[A-Za-z0-9._/-]*$/.test(path), `Unsupported probe path: ${path}`);
43	  const r = await exec(
44	    conn,
45	    `f=$(mktemp); c=$(curl -sS -k -L --max-redirs 5 --max-time 25 ` +
46	      `--resolve ${shellQuote(`${domain}:80:127.0.0.1`)} --resolve ${shellQuote(`${domain}:443:127.0.0.1`)} ` +
47	      `-o "$f" -w '%{http_code}' ${shellQuote(`http://${domain}${path}`)} 2>/dev/null); ` +
48	      `[ -n "$c" ] || c=000; printf 'NXCODE:%s\\n' "$c"; head -c 8192 "$f" 2>/dev/null; rm -f "$f"`,
49	    SETUP_TIMEOUT_MS
50	  );
51	  const out = String(r.stdout ?? "");
52	  const m = /NXCODE:(\d{3})/.exec(out);
53	  const nl = out.indexOf("\n");
54	  // Keep newlines: stripping them would glue words together and make markers
55	  // unmatchable (see probeBody in worker/migrate-real.ts).
56	  // eslint-disable-next-line no-control-regex
57	  const body = (nl < 0 ? "" : out.slice(nl + 1)).replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, " ");
58	  return { code: m ? m[1] : "000", body };
59	}
60	
61	/**
62	 * Run every probe for the app. Throws with the real HTTP result on the first
63	 * failure — an install that cannot be proved is a FAILED install, never a
64	 * quietly-downgraded one. Returns a one-line proof for the audit trail.
65	 */
66	export async function verifyServing(conn: Client, domain: string, probes: Probe[]): Promise<string> {
67	  const proof: string[] = [];
68	  for (const p of probes) {
69	    const { code, body } = await httpProbe(conn, domain, p.path);
70	    if (!(p.codes ?? ["200"]).includes(code))
71	      throw new Error(`verification failed: ${p.path} returned HTTP ${code}, so ${p.proves} is not true.`);
72	    for (const re of p.reject ?? []) {
73	      const hit = re.exec(body);
74	      if (hit) throw new Error(`verification failed: ${p.path} returned an application error ("${hit[0].slice(0, 80)}").`);
75	    }
76	    for (const re of p.require) {
77	      if (!re.test(body))
78	        throw new Error(`verification failed: ${p.path} answered 200 but ${p.proves} could not be confirmed.`);
79	    }
80	    proof.push(`${p.path}=${code}`);
81	  }
82	  return `verified from the VM (${proof.join(" ")})`;
83	}
