1	import { execFile } from "node:child_process";
2	import { promisify } from "node:util";
3	import { db } from "../lib/db";
4	import {
5	  planNatRules,
6	  reconcileNatChain,
7	  ruleSpec,
8	  type ForwardSource,
9	  type NatHost,
10	  type NatRule,
11	  type NatSyncResult,
12	} from "../lib/nat-rules";
13	
14	const exec = promisify(execFile);
15	
16	const CHAIN = process.env.NXEON_NAT_CHAIN ?? "NXEON_FWD";
17	
18	async function iptables(args: string[]) {
19	  await exec("iptables", args);
20	}
21	
22	async function ensureChain() {
23	  try {
24	    await iptables(["-t", "nat", "-N", CHAIN]);
25	  } catch {
26	    /* chain exists */
27	  }
28	  // Ensure PREROUTING jumps to our chain exactly once
29	  try {
30	    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", CHAIN]);
31	  } catch {
32	    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", CHAIN]);
33	  }
34	}
