36	/**
37	 * The real, iptables-backed NatHost — the only implementation production uses.
38	 * The decision logic it is handed to lives in lib/nat-rules.ts and is tested
39	 * against an in-memory fake; see the H5 incident note at the top of that file.
40	 */
41	function iptablesHost(): NatHost {
42	  return {
43	    ensureChain,
44	    listChain: async () => {
45	      const { stdout } = await exec("iptables", ["-t", "nat", "-S", CHAIN]);
46	      return stdout;
47	    },
48	    addRule: (r: NatRule) => iptables(["-t", "nat", "-A", CHAIN, ...ruleSpec(r)]),
49	    deleteRule: (r: NatRule) => iptables(["-t", "nat", "-D", CHAIN, ...ruleSpec(r)]),
50	  };
51	}
