53	/**
54	 * Reconcile the NXEON_FWD chain with the database, and verify the result.
55	 *
56	 * This used to open with `iptables -t nat -F NXEON_FWD` and rebuild the chain in
57	 * an unguarded loop, so a single failed `-A` aborted the rebuild and left every
58	 * subsequent server with no DNAT rule — a fleet-wide SSH blackhole that reported
59	 * DONE, because DONE meant "the last iptables call exited 0" (incident H5).
60	 *
61	 * There is no flush now. `reconcileNatChain` reads the chain, applies only the
62	 * difference, then reads it BACK and throws with the exact missing rules and the
63	 * command to inspect them if the kernel does not hold what the database says it
64	 * should. Rules that were already correct are never removed, so no failure in
65	 * this path can take down a customer who was working before it ran.
66	 *
67	 * Throws on an unproven ruleset — callers that cannot tolerate a throw must say
68	 * so; `remove()` in worker/index.ts calls this after deleting the server row, so
69	 * a throw there re-queues DELETE onto a row that no longer exists. That caller
70	 * uses `syncPortForwardsBestEffort` below.
71	 */
72	export async function syncPortForwards(): Promise<NatSyncResult> {
73	  const servers = await db.server.findMany({
74	    where: {
75	      ipAddress: { not: null },
76	      sshPort: { not: null },
77	      status: { notIn: ["SUSPENDED", "DELETING"] },
78	    },
79	    include: { portForwards: true },
80	  });
81	
82	  const intent = planNatRules(servers as unknown as ForwardSource[]);
83	
84	  // Two data problems that used to be invisible because the old loop just built
85	  // whatever it was handed. Neither blocks the sync — the ruleset we install is
86	  // still verified end to end — but neither is swallowed either.
87	  for (const c of intent.conflicts) {
88	    console.error(
89	      `[nat] port collision: ${c.proto}/${c.dport} is claimed by ${c.winner} and also by ` +
90	        `${c.losers.join(", ")}. Only ${c.winner} is forwarded; the others get NOTHING on that port.`
91	    );
92	  }
93	  for (const r of intent.rejected) {
94	    console.error(`[nat] ${r.hostname}: no rule installed — ${r.reason}`);
95	  }
96	
97	  const result = await reconcileNatChain(iptablesHost(), CHAIN, intent);
98	  if (result.unparsed.length) {
99	    console.warn(
100	      `[nat] ${CHAIN} contains ${result.unparsed.length} rule(s) this engine did not write and ` +
101	        `will not touch: ${result.unparsed.slice(0, 5).join(" | ")}`
102	    );
103	  }
104	  console.log(
105	    `[nat] ${CHAIN} verified: ${result.verified} rule(s) present (+${result.added} / -${result.deleted})`
106	  );
107	  return result;
108	}
