110	/**
111	 * For callers that must not be re-queued by a sync failure (server DELETE runs
112	 * this after the row is gone, so a throw dies on "Server not found" on retry and
113	 * the sync is never re-attempted — H5's aggravating factor).
114	 *
115	 * It still never claims success: the failure is logged in full and returned, so
116	 * the caller can surface it. What it will not do is convert a networking problem
117	 * into a stuck job that hides it.
118	 */
119	export async function syncPortForwardsBestEffort(context: string): Promise<Error | null> {
120	  try {
121	    await syncPortForwards();
122	    return null;
123	  } catch (e: any) {
124	    console.error(`[nat] port-forward sync FAILED after ${context} — forwarding may be wrong: ${e?.message ?? e}`);
125	    return e instanceof Error ? e : new Error(String(e));
126	  }
127	}
