14	/**
15	 * SSL certificate lifecycle: issuance (SSL_ISSUE), renewal, and reconciliation.
16	 *
17	 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
18	 *   SSL_ISSUE: sslIssue,
19	 * and put the lifecycle sweep on the loop's timer (same shape as
20	 * `lastBackupSweep` / `scheduledBackupSweep`):
21	 *   import { sslIssue, sslSweep } from "./ssl";
22	 *   let lastSslSweep = 0;
23	 *   if (Date.now() - lastSslSweep > 30 * 60_000) {
24	 *     lastSslSweep = Date.now();
25	 *     try { await sslSweep(); } catch (e) { console.error("[ssl] sweep error", e); }
26	 *   }
27	 *
28	 * Until 2026-07-26 `sslIssue` was the ONLY thing in this file. Certificates were
29	 * issued once and then never looked at again, so:
30	 *   - every certificate silently died at 90 days while the dashboard kept a green
31	 *     pulsing ACTIVE dot beside a neutral "Expires" date (EXPIRED was documented
32	 *     in the schema and written by nothing);
33	 *   - a row could sit in ISSUING forever if the worker was restarted mid-issue,
34	 *     and the customer could not even delete it;
35	 *   - `expiresAt` could be a computed now+90d guess rather than an observed date.
36	 * `sslSweep` fixes all three, and `verifyServed` reads back what is actually
37	 * being served so "active" means a certificate we have really seen.
38	 *
39	 * SAFETY: actually issuing a Let's Encrypt cert means SSHing to the customer's
40	 * VM and running certbot against a live, DNS-pointed domain. The real path runs
41	 * only when we're NOT in SANDBOX and ENABLE_REAL_SSL === "1"; in SANDBOX the
42	 * handler simulates, and outside SANDBOX without the flag it FAILS LOUDLY rather
43	 * than claiming a certificate that does not exist.
44	 */
45	
46	/**
47	 * A Let's Encrypt certificate is valid for 90 days. Used ONLY by the SANDBOX
48	 * simulation below, which labels itself as such. The real path must never
49	 * compute an expiry — see readObservedExpiry().
50	 */
51	const SANDBOX_CERT_LIFETIME_MS = 90 * 86400_000;
52	
53	/**
54	 * ACME account / contact email passed to certbot (`-m`). Let's Encrypt uses it
55	 * for expiry warnings. Override with CERTBOT_EMAIL; falls back to a constant.
56	 */
57	const CERTBOT_EMAIL = process.env.CERTBOT_EMAIL || "ssl-admin@nxeon.local";
58	
59	/** Overall SSH connect timeout, and per-certbot-command timeout. */
60	const SSH_CONNECT_TIMEOUT_MS = 15_000;
61	const CERTBOT_TIMEOUT_MS = 120_000;
62	/** Shorter budget for the quick pre-flight/install probes. */
63	const PROBE_TIMEOUT_MS = 60_000;
64	
65	// ---------------------------------------------------------------------------
66	// Lifecycle tuning
67	// ---------------------------------------------------------------------------
68	
69	/**
70	 * Renew when 21 days or less remain. Two hard constraints pin this number:
71	 *  - certbot only renews a lineage when fewer than 30 days remain. Asking
72	 *    earlier is a no-op ("Certificate not yet due for renewal"), so a 30-day
73	 *    lead would SSH into the customer's VM every sweep and achieve nothing.
74	 *  - the retry ladder below spends up to ~4.25 days inside one rate-limit
75	 *    window, so we need several windows of runway before the cert actually dies.
76	 * 21 days sits inside certbot's own window and still leaves three weeks of slack.
77	 */
78	const RENEW_LEAD_MS = 21 * 86400_000;
79	
80	/**
81	 * Rolling window and hard caps for issue attempts against ONE hostname.
82	 *
83	 * `MAX_LE_ATTEMPTS_PER_WINDOW` protects Let's Encrypt's limit of 5 duplicate
84	 * certificates (identical hostname set) per week. Exceeding it locks the customer
85	 * out of HTTPS for a full week — far worse than renewing a day late — so we stop
86	 * at 4 and leave one slot for the customer's own manual "Renew now".
87	 *
88	 * `MAX_TOTAL_ATTEMPTS_PER_WINDOW` counts attempts that never reached Let's
89	 * Encrypt as well. Those cost no rate-limit slot, but they are the ones that
90	 * repeat forever (port 80 permanently occupied, certbot uninstallable), and
91	 * without a cap the sweep would SSH into the customer's VM to fail identically
92	 * every 30 minutes indefinitely.
93	 */
94	const ISSUE_WINDOW_MS = 7 * 86400_000;
95	const MAX_LE_ATTEMPTS_PER_WINDOW = 4;
96	const MAX_TOTAL_ATTEMPTS_PER_WINDOW = 6;
97	
98	/**
99	 * Wait required before the next attempt, indexed by how many attempts of ANY
100	 * kind have already been made for this hostname inside the current window: the
101	 * first is immediate, then 6h / 24h / 72h (the last value repeats).
102	 *
103	 * Indexing on the total — not just the rate-limit-relevant ones — is what makes
104	 * the sweep incapable of looping. A locally-failing attempt does not consume a
105	 * Let's Encrypt slot, so if backoff were keyed on the LE counter a permanently
106	 * broken server would be retried on every single sweep pass forever. Keyed on the
107	 * total, the ladder allows at most ~4 attempts per hostname per week (0h, 6h,
108	 * 30h, 102h, 174h > one window) however often the sweep runs.
109	 */
110	const RENEW_BACKOFF_MS = [0, 6 * 3600_000, 24 * 3600_000, 72 * 3600_000];
111	
112	/**
113	 * How long a PENDING row may sit with no SSL_ISSUE job at all before we call it
114	 * lost. A row that IS attached to a queued job is never aged out no matter how
115	 * long it waits — the queue is serial platform-wide and a genuine 40-minute wait
116	 * behind a MIGRATE is not a failure (the dashboard explains the wait instead).
117	 */
118	const ORPHAN_PENDING_MS = 15 * 60_000;
119	
120	/**
121	 * Grace after a terminal SSL_ISSUE job before we declare an ISSUING row orphaned.
122	 * Guards the tiny window between the handler returning and index.ts writing DONE.
123	 */
124	const ORPHAN_GRACE_MS = 2 * 60_000;
125	
126	/** TLS read-back of the certificate actually being served on :443. */
127	const TLS_PROBE_TIMEOUT_MS = 5_000;
128	
129	/**
130	 * Sweeps run INLINE in the worker's strictly serial `for(;;)` loop, so every
131	 * second spent here is a second no customer job runs. These caps keep a sweep
132	 * bounded well under a minute even with a large certificate table — the whole
133	 * point of P1-38/P1-1 is that a slow sweep is itself an outage.
134	 */
135	const MAX_CERTS_PER_SWEEP = 60;
136	const PROBE_BUDGET_MS = 25_000;
137	
138	/**
139	 * `Job.step` doubles as the machine-readable outcome of an SSL_ISSUE attempt.
140	 * We need it because the rate-limit counter must distinguish attempts that
141	 * really reached Let's Encrypt from ones that died locally (certbot missing,
142	 * port 80 busy, SSH refused). Without the distinction, a customer whose port 80
143	 * is occupied would be locked out for a week by failures LE never even saw.
144	 *
145	 * NOTE: the two "did not reach LE" values are duplicated in lib/actions-ssl.ts
146	 * (which cannot import this module — it would pull ssh2 into the Next bundle).
147	 * Keep them in sync.
148	 */
149	export const SSL_STEP_ISSUED = "certificate issued";
150	export const SSL_STEP_ACME_FAILED = "failed at the certbot/ACME step";
151	export const SSL_STEP_PREFLIGHT_FAILED = "failed before contacting Let's Encrypt";
152	export const SSL_STEP_SANDBOX = "simulated (sandbox)";
153	
154	/** Stable prefix so a repeated sweep can recognise its own pause note. */
155	const RENEWAL_PAUSED_PREFIX = "Automatic renewal is paused";
