165	/**
166	 * Send `title` at most once per `withinMs` for this user. The sweep runs every
167	 * 30 minutes; without this a customer with one un-renewable certificate would
168	 * collect ~50 identical notifications a day and stop reading any of them.
169	 */
170	async function notifyOnce(
171	  userId: string,
172	  title: string,
173	  body: string,
174	  withinMs: number
175	): Promise<void> {
176	  const recent = await db.notification.findFirst({
177	    where: { userId, title, createdAt: { gt: new Date(Date.now() - withinMs) } },
178	    select: { id: true },
179	  });
180	  if (recent) return;
181	  await notify(userId, title, body, "/dashboard/ssl");
