184	// ----------------------------------------------------------------------------
185	// Real issuance path (SSH + certbot). Only reachable when
186	// `!SANDBOX && ENABLE_REAL_SSL === "1"` — see the guard in sslIssue().
187	// ----------------------------------------------------------------------------
188	
189	type SshResult = { code: number | null; stdout: string; stderr: string };
190	
191	/**
192	 * Tracks whether an attempt got as far as invoking certbot. Passed in by
193	 * reference so the value survives the throw that unwinds out of the SSH block —
194	 * the rate-limit counter needs it (see SSL_STEP_* above).
195	 */
196	type IssuePhase = { reachedAcme: boolean };
197	
198	/**
199	 * Single-quote a value for safe interpolation into a POSIX shell command.
200	 * We already restrict the domain to a strict charset below, but everything that
201	 * reaches a remote shell is quoted defensively regardless.
202	 */
203	function shellQuote(s: string): string {
204	  return `'${s.replace(/'/g, `'\\''`)}'`;
205	}
206	
207	/** Domains must look like real hostnames before we hand them to certbot. */
208	function assertSafeDomain(domain: string): void {
209	  if (!/^(?=.{1,253}$)([a-zA-Z0-9-]{1,63}\.)+[a-zA-Z]{2,63}$/.test(domain)) {
210	    throw new Error(`Refusing to issue for an unexpected domain: ${domain}`);
211	  }
212	}
213	
214	/**
215	 * Run one command on an already-connected ssh2 client, capturing stdout/stderr
216	 * and the exit code. Rejects on transport error or if the command exceeds
217	 * `timeoutMs` (the channel is torn down so a hung certbot can't wedge the worker).
218	 */
219	function sshExec(conn: SshClient, command: string, timeoutMs: number): Promise<SshResult> {
220	  return new Promise((resolve, reject) => {
221	    conn.exec(command, (err, stream) => {
222	      if (err) return reject(err);
223	      let stdout = "";
224	      let stderr = "";
225	      let settled = false;
226	      const timer = setTimeout(() => {
227	        if (settled) return;
228	        settled = true;
229	        try {
230	          stream.close();
231	        } catch {
232	          /* best effort */
233	        }
234	        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
235	      }, timeoutMs);
236	
237	      stream
238	        .on("close", (code: number | null) => {
239	          if (settled) return;
240	          settled = true;
241	          clearTimeout(timer);
242	          resolve({ code, stdout, stderr });
243	        })
244	        .on("data", (d: Buffer) => {
245	          stdout += d.toString("utf8");
246	        })
247	        .stderr.on("data", (d: Buffer) => {
248	          stderr += d.toString("utf8");
249	        });
250	    });
251	  });
252	}
