254	/** Open an ssh2 connection to a server, run `fn`, and always end the connection. */
255	async function withSsh<T>(
256	  target: { host: string; port: number },
257	  password: string,
258	  fn: (conn: SshClient) => Promise<T>
259	): Promise<T> {
260	  const conn = new SshClient();
261	  await new Promise<void>((resolve, reject) => {
262	    const timer = setTimeout(() => {
263	      try {
264	        conn.end();
265	      } catch {
266	        /* best effort */
267	      }
268	      reject(new Error(`SSH connect timed out after ${Math.round(SSH_CONNECT_TIMEOUT_MS / 1000)}s`));
269	    }, SSH_CONNECT_TIMEOUT_MS);
270	    conn
271	      .on("ready", () => {
272	        clearTimeout(timer);
273	        resolve();
274	      })
275	      .on("error", (e) => {
276	        clearTimeout(timer);
277	        reject(e);
278	      })
279	      .connect({
280	        host: target.host,
281	        port: target.port,
282	        username: "root",
283	        password,
284	        readyTimeout: SSH_CONNECT_TIMEOUT_MS,
285	      });
286	  });
287	  try {
288	    return await fn(conn);
289	  } finally {
290	    try {
291	      conn.end();
292	    } catch {
293	      /* best effort */
294	    }
295	  }
296	}
