298	/**
299	 * Read the certificate's REAL notAfter off the customer's VM.
300	 *
301	 * There is deliberately no fallback. The previous version defaulted to
302	 * `now + 90 days` whenever `openssl x509 -enddate` could not be parsed, which is
303	 * how a row could claim ACTIVE with an expiry nobody had ever observed — the same
304	 * class of lie as the simulated-success branch. If we cannot read the date, the
305	 * attempt is a failure and says so; re-requesting is cheap because certbot reuses
306	 * a still-valid certificate without asking Let's Encrypt again.
307	 */
308	async function readObservedExpiry(conn: SshClient, domain: string): Promise<Date> {
309	  const live = `/etc/letsencrypt/live/${domain}/fullchain.pem`;
310	  const enddate = await sshExec(
311	    conn,
312	    `openssl x509 -enddate -noout -in ${shellQuote(live)} 2>&1 || true`,
313	    PROBE_TIMEOUT_MS
314	  );
315	  const m = enddate.stdout.match(/notAfter=(.+)/);
316	  const parsed = m ? new Date(m[1].trim()) : null;
317	  if (!parsed || Number.isNaN(parsed.getTime())) {
318	    throw new Error(
319	      `certbot reported success but the certificate's real expiry could not be read back from ${live} ` +
320	        `(${(enddate.stdout || "no output").trim().slice(0, 160)}). We do not report a certificate as ` +
321	        `active on a guessed expiry date, so this attempt is recorded as failed. Requesting again is safe.`
322	    );
323	  }
324	  return parsed;
325	}
