327	/**
328	 * Really issue a Let's Encrypt certificate for `cert.domain` by SSHing into the
329	 * customer's own VM (same host/port/root-password derivation as lib/sftp) and
330	 * driving certbot in --standalone mode. Throws on any failure so the caller's
331	 * catch marks the cert with the reason.
332	 *
333	 * Steps on the customer VM:
334	 *   1. Detect the package manager (apt-get / dnf) and ensure `certbot` exists,
335	 *      installing it if missing.
336	 *   2. Confirm TCP port 80 is free (standalone binds it for the HTTP-01
337	 *      challenge) — surface a clear error otherwise.
338	 *   3. certbot certonly --standalone -n --agree-tos -m <email> -d <domain>.
339	 *   4. Read the real notAfter back out of the issued fullchain (no guessing).
340	 *
341	 * Everything before step 3 sets nothing on `phase`; step 3 flips
342	 * `phase.reachedAcme` so a local pre-flight failure is not counted against the
343	 * Let's Encrypt weekly limit.
344	 */
345	async function issueRealCertificate(
346	  cert: SslCertificate,
347	  phase: IssuePhase
348	): Promise<{ issuedAt: Date | null; expiresAt: Date; reissued: boolean }> {
349	  const domain = cert.domain;
350	  assertSafeDomain(domain);
351	
352	  if (!cert.serverId) {
353	    throw new Error("Certificate is not attached to a server.");
354	  }
355	
356	  // Load exactly the fields connectionTarget()/SSH need (mirrors lib/sftp usage).
357	  const server = await db.server.findUnique({
358	    where: { id: cert.serverId },
359	    select: {
360	      id: true,
361	      rootPassword: true,
362	      rootPasswordEnc: true,
363	      sshPort: true,
364	      dedicatedIp: { select: { address: true } },
365	    },
366	  });
367	  if (!server) throw new Error(`Server ${cert.serverId} not found.`);
368	
369	  const target = connectionTarget(server as SftpServer);
370	  if (!target) {
371	    throw new Error("Server is not reachable yet — connection details are pending.");
372	  }
373	  const rootPassword = serverRootPassword(server);
374	  if (!rootPassword) throw new Error("Server has no root password set.");
375	
376	  const qDomain = shellQuote(domain);
377	  const qEmail = shellQuote(CERTBOT_EMAIL);
378	
379	  return withSsh(target, rootPassword, async (conn) => {
380	    // 1. Ensure certbot is present. `command -v` is portable; install only if missing.
381	    const have = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
382	    if (have.stdout.trim() !== "yes") {
383	      // Pick the installer from whichever package manager exists.
384	      const pm = await sshExec(
385	        conn,
386	        "if command -v apt-get >/dev/null 2>&1; then echo apt; " +
387	          "elif command -v dnf >/dev/null 2>&1; then echo dnf; else echo none; fi",
388	        PROBE_TIMEOUT_MS
389	      );
390	      const which = pm.stdout.trim();
391	      let installCmd: string;
392	      if (which === "apt") {
393	        installCmd = "DEBIAN_FRONTEND=noninteractive apt-get update -y && apt-get install -y certbot";
394	      } else if (which === "dnf") {
395	        installCmd = "dnf install -y certbot";
396	      } else {
397	        throw new Error("No supported package manager (apt-get/dnf) found to install certbot.");
398	      }
399	      const inst = await sshExec(conn, installCmd, CERTBOT_TIMEOUT_MS);
400	      if (inst.code !== 0) {
401	        throw new Error(`certbot install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 300)}`);
402	      }
403	      // Re-check that certbot is now on PATH.
404	      const recheck = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
405	      if (recheck.stdout.trim() !== "yes") {
406	        throw new Error("certbot still not available after install.");
407	      }
408	    }
409	
410	    // 2. Standalone needs port 80. If something is already listening, bail with a
411	    //    clear message rather than letting certbot fail cryptically. (We default to
412	    //    --standalone; --webroot would only be used if a docroot were known.)
413	    const portCheck = await sshExec(
414	      conn,
415	      "ss -ltnH 'sport = :80' 2>/dev/null | head -n1 || true",
416	      PROBE_TIMEOUT_MS
417	    );
418	    if (portCheck.stdout.trim().length > 0) {
419	      throw new Error(
420	        "Port 80 is in use by another service; free it (or configure webroot issuance) before requesting a standalone certificate."
421	      );
422	    }
423	
424	    // 3. Issue. --standalone spins up certbot's own HTTP-01 responder on :80.
425	    //    From here on the attempt may have consumed a Let's Encrypt slot.
426	    const certbotCmd =
427	      `certbot certonly --standalone -n --agree-tos -m ${qEmail} -d ${qDomain}`;
428	    phase.reachedAcme = true;
429	    const run = await sshExec(conn, certbotCmd, CERTBOT_TIMEOUT_MS);
430	    const combined = `${run.stdout}\n${run.stderr}`;
431	    // certbot exits 0 BOTH when it issues and when it declines to, and
432	    // "Certificate not yet due for renewal" used to sit in the same success
433	    // alternation as "Congratulations" — so a no-op was reported as a renewal
434	    // and the unchanged expiry read back as if it were new (M7 #6). The exit
435	    // code decides nothing here; the classifier does.
436	    const outcome = classifyCertbotOutcome(run.code, combined);
437	    if (outcome.kind === "failed") {
438	      throw new Error(`certbot failed: ${outcome.detail}`);
439	    }
440	
441	    // 4. The expiry we persist is the one on the certificate, never a guess.
442	    const expiresAt = await readObservedExpiry(conn, domain);
443	    // `issuedAt` must not move when nothing was issued: a fresh issuedAt beside
444	    // an unchanged expiresAt is precisely the shape that read as a renewal.
445	    return { issuedAt: outcome.kind === "issued" ? new Date() : null, expiresAt, reissued: outcome.kind === "issued" };
446	  });
447	}
