449	// ----------------------------------------------------------------------------
450	// Read back what is actually being served (no SSH, no certbot, no ACME).
451	// ----------------------------------------------------------------------------
452	
453	type ServedCert =
454	  | ({ ok: true } & ServedIdentity)
455	  | { ok: false; reason: string };
456	
457	function tlsErrorReason(e: any): string {
458	  const code = String(e?.code ?? "");
459	  if (code === "ECONNREFUSED") return "nothing is listening on port 443";
460	  if (code === "ENOTFOUND" || code === "EAI_AGAIN") return "the domain does not resolve in DNS";
461	  if (code === "ETIMEDOUT") return "the connection to port 443 timed out";
462	  if (code === "ECONNRESET") return "the connection was reset before TLS finished";
463	  if (code === "EHOSTUNREACH" || code === "ENETUNREACH") return "the host is unreachable";
464	  return (String(e?.message ?? e) || code || "the TLS connection failed").slice(0, 140);
465	}
466	
467	/** Does a certificate name (possibly `*.example.com`) cover `domain`? */
468	function hostMatches(name: string, domain: string): boolean {
469	  const n = name.trim().toLowerCase();
470	  const d = domain.trim().toLowerCase();
471	  if (!n) return false;
472	  if (n === d) return true;
473	  if (n.startsWith("*.")) {
474	    // A wildcard covers exactly one label, so the label counts must match.
475	    return d.endsWith(n.slice(1)) && d.split(".").length === n.split(".").length;
476	  }
477	  return false;
478	}
479	
480	/**
481	 * Open a plain TLS connection to `domain:443` and read the certificate the
482	 * public internet is actually being handed.
483	 *
484	 * This is the cheap, honest half of "is it really active": certbot --standalone
485	 * OBTAINS a certificate but does not install it into nginx/apache, so
486	 * issued-and-not-served is the normal outcome, not an edge case. Reading it back
487	 * is the only way the dashboard can tell the difference — and it costs one
488	 * handshake to a public hostname, no SSH and no ACME.
489	 *
490	 * `rejectUnauthorized: false` is deliberate: an expired, self-signed or
491	 * wrong-name certificate is exactly the state the customer needs to be told
492	 * about, and refusing the handshake would throw that information away. Nothing
493	 * is ever sent over this socket.
494	 *
495	 * But NOT rejecting is not the same as not LOOKING. Until M7 #5 this function
496	 * returned only the expiry and a name match, so a self-signed certificate read
497	 * as ACTIVE and a CDN's edge certificate was indistinguishable from our own —
498	 * which is how an origin certificate could expire behind Cloudflare while the
499	 * row kept adopting the edge's date. We now also capture `socket.authorized`
500	 * (Node performs the verification either way and records the result) and the
501	 * issuer, and `servedCertVerdict` decides what those facts permit us to claim.
502	 */
503	function probeServedCertificate(domain: string): Promise<ServedCert> {
504	  return new Promise((resolve) => {
505	    let settled = false;
506	    let socket: ReturnType<typeof tlsConnect> | null = null;
507	    const done = (r: ServedCert) => {
508	      if (settled) return;
509	      settled = true;
510	      try {
511	        socket?.destroy();
512	      } catch {
513	        /* best effort */
514	      }
515	      resolve(r);
516	    };
517	
518	    try {
519	      socket = tlsConnect(
520	        {
521	          host: domain,
522	          port: 443,
523	          servername: domain,
524	          rejectUnauthorized: false,
525	        },
526	        () => {
527	          try {
528	            const peer = socket!.getPeerCertificate();
529	            if (!peer || !peer.valid_to) {
530	              return done({ ok: false, reason: "the server presented no certificate" });
531	            }
532	            const notAfter = new Date(peer.valid_to);
533	            if (Number.isNaN(notAfter.getTime())) {
534	              return done({ ok: false, reason: `its expiry date was unreadable (${peer.valid_to})` });
535	            }
536	            const names: string[] = [];
537	            if (peer.subject?.CN) names.push(String(peer.subject.CN));
538	            for (const entry of String(peer.subjectaltname ?? "").split(",")) {
539	              const t = entry.trim();
540	              if (t.toLowerCase().startsWith("dns:")) names.push(t.slice(4));
541	            }
542	            done({
543	              ok: true,
544	              notAfter,
545	              coversDomain: names.some((n) => hostMatches(n, domain)),
546	              issuerCN: String(peer.issuer?.CN ?? ""),
547	              issuerO: String(peer.issuer?.O ?? ""),
548	              authorized: socket!.authorized === true,
549	              authorizationError: String((socket as any)!.authorizationError ?? ""),
550	            });
551	          } catch (e: any) {
552	            done({ ok: false, reason: String(e?.message ?? e).slice(0, 140) });
553	          }
554	        }
555	      );
556	      // Idle timeout covers the connect phase too, so a black-holed host cannot
557	      // hold the serial worker loop open.
558	      socket.setTimeout(TLS_PROBE_TIMEOUT_MS, () =>
559	        done({ ok: false, reason: `port 443 did not respond within ${Math.round(TLS_PROBE_TIMEOUT_MS / 1000)}s` })
560	      );
561	      socket.on("error", (e: any) => done({ ok: false, reason: tlsErrorReason(e) }));
562	    } catch (e: any) {
563	      done({ ok: false, reason: tlsErrorReason(e) });
564	    }
565	  });
566	}
