568	// Deterministic warning texts. They are compared for equality below so a sweep
569	// can recognise a note it wrote itself and avoid overwriting a real error.
570	function notServedWarning(domain: string, reason: string): string {
571	  return (
572	    `The certificate exists, but nothing is serving it for https://${domain} — ${reason}. ` +
573	    `certbot obtains the certificate in standalone mode; it does not install it into your web server. ` +
574	    `Point your TLS config at /etc/letsencrypt/live/${domain}/fullchain.pem and privkey.pem, then reload it.`
575	  );
576	}
577	
578	function wrongNameWarning(domain: string): string {
579	  return (
580	    `Port 443 on ${domain} is serving a certificate issued for a different hostname, so visitors get ` +
581	    `NET::ERR_CERT_COMMON_NAME_INVALID. Check which certificate your web server is configured to use.`
582	  );
583	}
