585	/**
586	 * Is `s` one of our own probe notes (rather than a real issuance/renewal error)?
587	 *
588	 * Every string `servedCertVerdict` can produce must be listed here, or the note
589	 * becomes sticky: it would be mistaken for a genuine issuance error, so the next
590	 * clean probe would refuse to clear it and the row would nag forever about a
591	 * condition that has been fixed.
592	 */
593	function isProbeWarning(s: string | null): boolean {
594	  if (!s) return false;
595	  return (
596	    s.includes("nothing is serving it for https://") ||
597	    s.includes("issued for a different hostname") ||
598	    s.includes("is NOT trusted by browsers") ||
599	    s.includes("it is NOT the certificate we issued") ||
600	    s.includes("Visitors see a browser security warning until a new one is installed")
601	  );
602	}
603	
604	/**
605	 * Make a row match the certificate the internet can actually see, and return the
606	 * expiry we now believe (observed if we could read one).
607	 *
608	 * This is where "honest status" is enforced: `expiresAt` becomes the observed
609	 * notAfter, an out-of-band renewal (certbot installs its own systemd timer on the
610	 * VM, so certificates do renew without us) is picked up instead of triggering a
611	 * pointless reissue, and an issued-but-not-installed certificate gets a visible
612	 * note instead of a silent green dot.
613	 */
614	async function verifyServed(cert: SslCertificate): Promise<Date | null> {
615	  const served = await probeServedCertificate(cert.domain);
616	  const now = Date.now();
617	
618	  if (!served.ok) {
619	    // Nothing answered on 443. Keep the issuer-read expiry (still the best
620	    // observed value we have) but say so — and never clobber a genuine
621	    // renewal/issuance error with a probe note.
622	    const note = notServedWarning(cert.domain, served.reason);
623	    if ((cert.lastError === null || isProbeWarning(cert.lastError)) && cert.lastError !== note) {
624	      await db.sslCertificate.update({ where: { id: cert.id }, data: { lastError: note } });
625	    }
626	    return cert.expiresAt;
627	  }
628	
629	  const verdict = servedCertVerdict({
630	    domain: cert.domain,
631	    served,
632	    recordedExpiry: cert.expiresAt,
633	    ourIssuer: cert.issuer,
634	    now,
635	  });
636	
637	  // `adoptExpiry` is the M7 #5 gate. We only overwrite our record of OUR
638	  // certificate's expiry when the certificate on the wire is one we can believe
639	  // is ours — otherwise a CDN edge certificate's date silently replaces the
640	  // origin's and the origin is never renewed again.
641	  const nextExpiry = verdict.adoptExpiry ? served.notAfter : cert.expiresAt;
642	  const nextStatus = verdict.status ?? cert.status;
643	
644	  // A probe note must still never overwrite a real issuance/renewal error.
645	  const keepExisting = cert.lastError !== null && !isProbeWarning(cert.lastError);
646	  const nextError = keepExisting ? cert.lastError : verdict.note;
647	
648	  const changed =
649	    cert.status !== nextStatus ||
650	    cert.expiresAt?.getTime() !== nextExpiry?.getTime() ||
651	    cert.lastError !== nextError;
652	  if (changed) {
653	    await db.sslCertificate.update({
654	      where: { id: cert.id },
655	      data: { status: nextStatus, expiresAt: nextExpiry, lastError: nextError },
656	    });
657	  }
658	  return nextExpiry;
659	}
