661	// ----------------------------------------------------------------------------
662	// SSL_ISSUE handler
663	// ----------------------------------------------------------------------------
664	
665	type SslPayload = { certId?: string; domain?: string; renewal?: boolean };
666	
667	function payloadOf(job: { payload: unknown }): SslPayload {
668	  return (job.payload ?? {}) as SslPayload;
669	}
670	
671	export async function sslIssue(job: Job): Promise<void> {
672	  const payload = payloadOf(job);
673	  if (!payload.certId) throw new Error("ssl job: missing certId");
674	  const isRenewal = payload.renewal === true;
675	
676	  const cert = await db.sslCertificate.findUnique({ where: { id: payload.certId } });
677	  if (!cert) throw new Error(`SslCertificate ${payload.certId} not found`);
678	
679	  /** Record the outcome on the job so the rate-limit counter can classify it. */
680	  const markStep = async (step: string) => {
681	    await db.job.update({ where: { id: job.id }, data: { step } }).catch(() => {
682	      /* the outcome marker is an optimisation; never fail the job over it */
683	    });
684	  };
685	
686	  // Mark in-flight so the UI shows "issuing" while we work. On a renewal the row
687	  // keeps its existing expiresAt, so the dashboard can still say "current
688	  // certificate valid until <date>" instead of implying the site is down.
689	  await db.sslCertificate.update({ where: { id: cert.id }, data: { status: "ISSUING" } });
690	
691	  const phase: IssuePhase = { reachedAcme: false };
692	
693	  try {
694	    // ---------------------------------------------------------------------
695	    // Real issuance path (SSH + certbot). Guarded so it can never run by
696	    // accident: it happens ONLY when ENABLE_REAL_SSL is explicitly set AND we
697	    // are not in SANDBOX.
698	    // ---------------------------------------------------------------------
699	    const realIssuanceEnabled = !SANDBOX && process.env.ENABLE_REAL_SSL === "1";
700	    if (realIssuanceEnabled) {
701	      const { issuedAt, expiresAt, reissued } = await issueRealCertificate(cert, phase);
702	
703	      // Immediately read back what the domain actually serves. certbot
704	      // --standalone does NOT wire the certificate into nginx/apache, so the
705	      // common outcome of a successful issue is "obtained but not installed" —
706	      // telling the customer their site is now HTTPS would be wrong.
707	      let installNote: string | null = null;
708	      if (!SANDBOX) {
709	        const served = await probeServedCertificate(cert.domain);
710	        if (!served.ok) installNote = notServedWarning(cert.domain, served.reason);
711	        else if (!served.coversDomain) installNote = wrongNameWarning(cert.domain);
712	      }
713	
714	      await db.sslCertificate.update({
715	        where: { id: cert.id },
716	        // issuedAt only moves when a certificate was really issued.
717	        data: { status: "ACTIVE", ...(issuedAt ? { issuedAt } : {}), expiresAt, lastError: installNote },
718	      });
719	      await markStep(SSL_STEP_ISSUED);
720	      // "renewed" is a claim about an event, and it is only made when the event
721	      // happened. A no-op run says so, and says what it means (M7 #6).
722	      const verb = reissued ? (isRenewal ? "renewed" : "issued") : "unchanged";
723	      await notify(
724	        cert.userId,
725	        reissued
726	          ? `SSL certificate ${isRenewal ? "renewed" : "issued"} for ${cert.domain}`
727	          : `SSL certificate for ${cert.domain} was NOT renewed`,
728	        !reissued
729	          ? unchangedRenewalNote(cert.domain, expiresAt, isRenewal)
730	          : installNote
731	          ? `Obtained, valid until ${expiresAt.toISOString().slice(0, 10)} — but not yet installed in your web server.`
732	          : `Verified live on https://${cert.domain}, valid until ${expiresAt.toISOString().slice(0, 10)}.`,
733	        "/dashboard/ssl"
734	      );
735	      return;
736	    }
737	
738	    // Simulation is a SANDBOX affordance and MUST NEVER run in production.
739	    //
740	    // Until 2026-07-25 it did: production has no ENABLE_REAL_SSL, so every real
741	    // customer request fell through to the block below, which wrote status
742	    // "ACTIVE" with an invented 90-day expiry and told them "your Let's Encrypt
743	    // certificate is active" — while no certbot had run and no certificate
744	    // existed. Identical in kind to the migration reporting "Sites serving: 4/4"
745	    // with six domains dark: the system asserting an outcome it never verified.
746	    //
747	    // A certificate we did not issue is a FAILURE, and it must say so loudly
748	    // enough that an operator notices the flag is missing.
749	    if (!SANDBOX) {
750	      throw new Error(
751	        "Certificate issuance is switched off on this server (ENABLE_REAL_SSL is not set), " +
752	          "so no certificate was requested from Let's Encrypt. Nothing was installed — " +
753	          "this certificate is NOT active. Ask support to enable real issuance."
754	      );
755	    }
756	
757	    // Default: simulated success (SANDBOX-only, no SSH, no certbot).
758	    const now = new Date();
759	    await db.sslCertificate.update({
760	      where: { id: cert.id },
761	      data: {
762	        status: "ACTIVE",
763	        issuedAt: now,
764	        expiresAt: new Date(now.getTime() + SANDBOX_CERT_LIFETIME_MS),
765	        lastError: null,
766	      },
767	    });
768	    await markStep(SSL_STEP_SANDBOX);
769	    await notify(
770	      cert.userId,
771	      `SSL certificate ${isRenewal ? "renewed" : "issued"} for ${cert.domain}`,
772	      "Your Let's Encrypt certificate is active and valid for 90 days (sandbox).",
773	      "/dashboard/ssl"
774	    );
775	  } catch (e: any) {
776	    const reason = String(e?.message ?? e).slice(0, 500);
777	
778	    // A failed RENEWAL must not erase the fact that the current certificate is
779	    // still serving traffic. Flipping a cert with 20 valid days left to FAILED is
780	    // its own kind of lie — it would panic a customer whose site is fine.
781	    //
782	    // `cert` was read before this attempt set ISSUING, so cert.status is the
783	    // pre-attempt status: only a row that really was live can come back as
784	    // ACTIVE/EXPIRED. A reissue of a FAILED row that fails again stays FAILED, so
785	    // a retry can never launder a row into looking like it once worked.
786	    const wasLive = cert.status === "ACTIVE" || cert.status === "EXPIRED";
787	    let status: string;
788	    if (isRenewal && wasLive && cert.expiresAt && cert.expiresAt.getTime() > Date.now()) {
789	      status = "ACTIVE";
790	    } else if (isRenewal && wasLive) {
791	      status = "EXPIRED";
792	    } else {
793	      status = "FAILED";
794	    }
795	
796	    const detail = isRenewal ? `Renewal failed: ${reason}`.slice(0, 500) : reason;
797	    await db.sslCertificate.update({
798	      where: { id: cert.id },
799	      data: { status, lastError: detail },
800	    });
801	    await markStep(phase.reachedAcme ? SSL_STEP_ACME_FAILED : SSL_STEP_PREFLIGHT_FAILED);
802	    await notify(
803	      cert.userId,
804	      `SSL certificate ${isRenewal ? "renewal" : "request"} failed for ${cert.domain}`,
805	      detail.slice(0, 200),
806	      "/dashboard/ssl"
807	    );
808	  }
809	}
