811	// ----------------------------------------------------------------------------
812	// Lifecycle sweep: reconcile stalled/expired rows, then renew what is due.
813	// ----------------------------------------------------------------------------
814	
815	type Attempt = {
816	  /** Every attempt, including ones that never reached the ACME server. */
817	  total: number;
818	  /** Attempts that may have consumed a Let's Encrypt duplicate-cert slot. */
819	  leRelevant: number;
820	  lastAt: Date;
821	};
822	
823	/**
824	 * Whether an SSL_ISSUE attempt should be counted against the Let's Encrypt
825	 * weekly limit. Attempts that died locally (no certbot, port 80 busy, SSH
826	 * refused) never reached the ACME server and must NOT count — otherwise a
827	 * customer with a busy port 80 gets locked out of certificates for a week by
828	 * failures Let's Encrypt never saw. `null` (in flight, or a legacy row) counts:
829	 * when in doubt, protect the limit.
830	 */
831	function attemptCountsAgainstLimit(step: string | null): boolean {
832	  return step !== SSL_STEP_PREFLIGHT_FAILED && step !== SSL_STEP_SANDBOX;
833	}
834	
835	/**
836	 * Issue attempts in the current window, keyed by DOMAIN — not by certificate id.
837	 *
838	 * The key matters: Let's Encrypt's duplicate-certificate limit is per identical
839	 * hostname set, and deleting a row and requesting it again mints a fresh certId.
840	 * A per-certId counter would therefore reset on every delete/re-request, letting
841	 * a frustrated customer burn all five weekly slots in minutes and lose HTTPS for
842	 * a week.
843	 */
844	async function loadIssueHistory(): Promise<Map<string, Attempt>> {
845	  const since = new Date(Date.now() - ISSUE_WINDOW_MS);
846	  const jobs = await db.job.findMany({
847	    where: { type: "SSL_ISSUE", createdAt: { gt: since } },
848	    select: { payload: true, step: true, createdAt: true },
849	    orderBy: { createdAt: "asc" },
850	  });
851	  const map = new Map<string, Attempt>();
852	  for (const j of jobs) {
853	    const domain = payloadOf(j).domain;
854	    if (!domain) continue; // pre-2026-07-26 jobs carried only certId
855	    const prev = map.get(domain);
856	    map.set(domain, {
857	      total: (prev?.total ?? 0) + 1,
858	      leRelevant: (prev?.leRelevant ?? 0) + (attemptCountsAgainstLimit(j.step) ? 1 : 0),
859	      lastAt: j.createdAt,
860	    });
861	  }
862	  return map;
863	}
864	
865	/** Live (queued or running) SSL_ISSUE jobs, indexed by the cert they belong to. */
866	async function loadLiveIssueJobs() {
867	  const jobs = await db.job.findMany({
868	    where: { type: "SSL_ISSUE", status: { in: ["QUEUED", "RUNNING"] } },
869	    select: { id: true, status: true, createdAt: true, payload: true },
870	    orderBy: { createdAt: "asc" },
871	  });
872	  const byCert = new Map<string, (typeof jobs)[number]>();
873	  for (const j of jobs) {
874	    const certId = payloadOf(j).certId;
875	    if (certId && !byCert.has(certId)) byCert.set(certId, j);
876	  }
877	  return byCert;
878	}
