880	/**
881	 * Age out rows that can no longer make progress, and write EXPIRED.
882	 *
883	 * Two real failures this prevents:
884	 *  - the worker is restarted mid-issue, `reapStuckJobs` retires the job, and the
885	 *    certificate row sits in ISSUING forever. The customer could not even delete
886	 *    it (lib/actions-ssl.ts refused to delete an ISSUING row), so the domain was
887	 *    permanently unrequestable — requestCertificate rejects duplicates while a
888	 *    PENDING/ISSUING/ACTIVE row exists.
889	 *  - a certificate passes its expiry and keeps a green pulsing ACTIVE dot while
890	 *    every visitor gets NET::ERR_CERT_DATE_INVALID. EXPIRED was documented in the
891	 *    schema and written by nothing.
892	 */
893	export async function sslReconcileSweep(): Promise<void> {
894	  const now = Date.now();
895	
896	  const inflight = await db.sslCertificate.findMany({
897	    where: { status: { in: ["PENDING", "ISSUING"] } },
898	    take: MAX_CERTS_PER_SWEEP,
899	  });
900	
901	  if (inflight.length > 0) {
902	    const live = await loadLiveIssueJobs();
903	    const terminal = await db.job.findMany({
904	      where: {
905	        type: "SSL_ISSUE",
906	        status: { in: ["DONE", "FAILED"] },
907	        createdAt: { gt: new Date(now - ISSUE_WINDOW_MS) },
908	      },
909	      select: { status: true, error: true, updatedAt: true, payload: true },
910	      orderBy: { createdAt: "desc" },
911	    });
912	
913	    let cleared = 0;
914	    for (const cert of inflight) {
915	      // A row attached to a queued/running job is NOT stalled, however long it
916	      // has waited: the worker is a single serial queue platform-wide, so a
917	      // legitimate wait behind a MIGRATE can be tens of minutes. The dashboard
918	      // explains that wait instead (see the queue position on /dashboard/ssl).
919	      if (live.has(cert.id)) continue;
920	
921	      const last = terminal.find((j) => payloadOf(j).certId === cert.id);
922	      const ageMs = now - cert.createdAt.getTime();
923	      let reason: string | null = null;
924	
925	      if (last?.status === "FAILED" && now - last.updatedAt.getTime() > ORPHAN_GRACE_MS) {
926	        reason =
927	          `Issuance stopped before it finished — the worker job failed terminally` +
928	          `${last.error ? `: ${last.error.slice(0, 200)}` : " (no error recorded)"}. ` +
929	          `No certificate was installed, so this is not active. You can delete this row and request it again.`;
930	      } else if (last?.status === "DONE" && now - last.updatedAt.getTime() > ORPHAN_GRACE_MS) {
931	        reason =
932	          `Issuance ended without recording a result — the worker was interrupted after the certbot step. ` +
933	          `We cannot confirm a certificate exists, so this is not being reported as active. Request it again.`;
934	      } else if (!last && ageMs > ORPHAN_PENDING_MS) {
935	        reason =
936	          `No issuance job ever ran for this request — it was queued ${Math.round(ageMs / 60_000)} minutes ago ` +
937	          `and never picked up. Nothing was installed. Request it again.`;
938	      }
939	
940	      if (!reason) continue;
941	      await db.sslCertificate.update({
942	        where: { id: cert.id },
943	        data: { status: "FAILED", lastError: reason.slice(0, 500) },
944	      });
945	      await notifyOnce(
946	        cert.userId,
947	        `SSL certificate request for ${cert.domain} did not complete`,
948	        reason.slice(0, 200),
949	        6 * 3600_000
950	      );
951	      cleared++;
952	    }
953	    if (cleared > 0) console.log(`[ssl] reconciled ${cleared} stalled certificate row(s)`);
954	  }
955	
956	  // Anything still flagged ACTIVE past its observed expiry is not active.
957	  const lapsed = await db.sslCertificate.findMany({
958	    where: { status: "ACTIVE", expiresAt: { lt: new Date(now) } },
959	    take: MAX_CERTS_PER_SWEEP,
960	  });
961	  for (const cert of lapsed) {
962	    await db.sslCertificate.update({ where: { id: cert.id }, data: { status: "EXPIRED" } });
963	    await notifyOnce(
964	      cert.userId,
965	      `SSL certificate expired for ${cert.domain}`,
966	      `The certificate expired on ${cert.expiresAt!.toISOString().slice(0, 10)}. Visitors now see a browser ` +
967	        `security warning on https://${cert.domain} until a new one is issued and installed.`,
968	      24 * 3600_000
969	    );
970	  }
971	  if (lapsed.length > 0) console.log(`[ssl] marked ${lapsed.length} certificate(s) EXPIRED`);
972	}
