974	/**
975	 * Reissue certificates before they die.
976	 *
977	 * There was no renewal of any kind before 2026-07-26: `SslCertificate.autoRenew`
978	 * was written by the dashboard switch and read only for display, so every
979	 * certificate the platform ever issued expired silently at 90 days.
980	 *
981	 * The order of operations here is deliberate — verify what is actually served
982	 * BEFORE deciding to reissue. certbot installs its own systemd renewal timer on
983	 * the customer's VM, so certificates frequently renew without us; reissuing on a
984	 * stale `expiresAt` would spend Let's Encrypt slots on work already done.
985	 */
986	export async function sslRenewalSweep(): Promise<void> {
987	  const now = Date.now();
988	  const dueBefore = new Date(now + RENEW_LEAD_MS);
989	
990	  const candidates = await db.sslCertificate.findMany({
991	    where: {
992	      OR: [
993	        { status: "ACTIVE", expiresAt: { lt: dueBefore } },
994	        // No observed expiry at all: we cannot prove this is valid, so treat it
995	        // as needing verification/reissue (still subject to every cap below).
996	        { status: "ACTIVE", expiresAt: null },
997	        { status: "EXPIRED" },
998	      ],
999	    },
1000	    orderBy: [{ expiresAt: "asc" }],
1001	    take: MAX_CERTS_PER_SWEEP,
1002	  });
1003	  if (candidates.length === 0) return;
1004	
1005	  const live = await loadLiveIssueJobs();
1006	  const history = await loadIssueHistory();
1007	  const probeDeadline = now + PROBE_BUDGET_MS;
1008	  let enqueued = 0;
1009	
1010	  for (const cert of candidates) {
1011	    // Never stack a second issue job on a certificate already being worked.
1012	    if (live.has(cert.id)) continue;
1013	
1014	    let expiresAt = cert.expiresAt;
1015	    let fresh = cert;
1016	    if (!SANDBOX && Date.now() < probeDeadline) {
1017	      // Sandbox domains are fictional, so the probe would only ever produce a
1018	      // scary "nothing is serving this" note there.
1019	      expiresAt = await verifyServed(cert);
1020	      const reloaded = await db.sslCertificate.findUnique({ where: { id: cert.id } });
1021	      if (!reloaded) continue;
1022	      fresh = reloaded;
1023	    }
1024	
1025	    // Re-evaluate against the observed expiry, not the one we started with.
1026	    const due = !expiresAt || expiresAt.getTime() - Date.now() <= RENEW_LEAD_MS;
1027	    if (!due) continue;
1028	
1029	    if (!fresh.autoRenew) {
1030	      // The switch is no longer decoration: off means we really do nothing, so
1031	      // the customer has to be told before the site breaks.
1032	      const when = expiresAt ? expiresAt.toISOString().slice(0, 10) : "an unknown date";
1033	      await notifyOnce(
1034	        fresh.userId,
1035	        `SSL certificate for ${fresh.domain} needs renewing`,
1036	        `Auto-renew is switched off for this certificate. It expires on ${when} and will not be replaced ` +
1037	          `automatically — turn auto-renew on, or renew it yourself, before then.`,
1038	        3 * 86400_000
1039	      );
1040	      continue;
1041	    }
1042	
1043	    const hist = history.get(fresh.domain);
1044	    const total = hist?.total ?? 0;
1045	    const leRelevant = hist?.leRelevant ?? 0;
1046	
1047	    if (leRelevant >= MAX_LE_ATTEMPTS_PER_WINDOW || total >= MAX_TOTAL_ATTEMPTS_PER_WINDOW) {
1048	      // Stop, visibly. The LE arm stops one slot short of the weekly limit; the
1049	      // total arm stops a permanently-broken server being retried forever.
1050	      const resumesAt = new Date((hist?.lastAt.getTime() ?? now) + ISSUE_WINDOW_MS);
1051	      const why =
1052	        leRelevant >= MAX_LE_ATTEMPTS_PER_WINDOW
1053	          ? `${leRelevant} certificate requests for ${fresh.domain} have reached Let's Encrypt in the last 7 days. ` +
1054	            `Let's Encrypt allows only 5 identical certificates per week, so we stop short of the limit rather ` +
1055	            `than lock you out of HTTPS entirely.`
1056	          : `${total} renewal attempts for ${fresh.domain} have failed in the last 7 days without reaching ` +
1057	            `Let's Encrypt, so retrying again would just fail the same way.`;
1058	      const note =
1059	        `${RENEWAL_PAUSED_PREFIX} until ${resumesAt.toISOString().slice(0, 16).replace("T", " ")} UTC: ` +
1060	        `${why} Fix the cause below, then renewal resumes on its own.` +
1061	        (fresh.lastError && !fresh.lastError.startsWith(RENEWAL_PAUSED_PREFIX)
1062	          ? ` Last error: ${fresh.lastError.slice(0, 160)}`
1063	          : "");
1064	      if (fresh.lastError !== note) {
1065	        await db.sslCertificate.update({
1066	          where: { id: fresh.id },
1067	          data: { lastError: note.slice(0, 500) },
1068	        });
1069	      }
1070	      await notifyOnce(
1071	        fresh.userId,
1072	        `SSL renewal paused for ${fresh.domain}`,
1073	        note.slice(0, 200),
1074	        3 * 86400_000
1075	      );
1076	      continue;
1077	    }
1078	
1079	    // Escalating backoff keyed on TOTAL attempts — see RENEW_BACKOFF_MS. This is
1080	    // the guard that makes a 30-minute sweep incapable of becoming a retry loop.
1081	    const wait = RENEW_BACKOFF_MS[Math.min(total, RENEW_BACKOFF_MS.length - 1)];
1082	    if (hist && Date.now() - hist.lastAt.getTime() < wait) continue;
1083	
1084	    // Respect the platform's one-in-flight-job-per-server invariant (same as
1085	    // scheduledBackupSweep) so a renewal never queues behind its own siblings.
1086	    if (fresh.serverId) {
1087	      const busy = await db.job.count({
1088	        where: { serverId: fresh.serverId, status: { in: ["QUEUED", "RUNNING"] } },
1089	      });
1090	      if (busy > 0) continue;
1091	    }
1092	
1093	    await db.job.create({
1094	      data: {
1095	        type: "SSL_ISSUE",
1096	        serverId: fresh.serverId,
1097	        // `domain` is what the rate-limit counter keys on; `renewal` tells the
1098	        // handler to keep a still-valid certificate ACTIVE if the reissue fails.
1099	        payload: { certId: fresh.id, domain: fresh.domain, renewal: true },
1100	      },
1101	    });
1102	    // Count it locally too, so two rows for the same hostname in one pass cannot
1103	    // both enqueue.
1104	    history.set(fresh.domain, { total: total + 1, leRelevant: leRelevant + 1, lastAt: new Date() });
1105	    enqueued++;
1106	  }
1107	
1108	  if (enqueued > 0) console.log(`[ssl] renewal sweep enqueued ${enqueued} reissue job(s)`);
1109	}
