102	export async function ensureNginx(conn: import("ssh2").Client): Promise<void> {
103	  const have = await exec(conn, "command -v nginx >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
104	  if (have.stdout.trim() !== "yes") {
105	    const prefix = await pkgInstallPrefix(conn);
106	    const inst = await exec(conn, `${prefix} nginx`, INSTALL_TIMEOUT_MS);
107	    if (inst.code !== 0) throw new Error(`nginx install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
108	  }
109	  // Ensure the sites-available/enabled layout exists (Debian/Ubuntu default).
110	  await exec(conn, "mkdir -p /etc/nginx/sites-available /etc/nginx/sites-enabled", SETUP_TIMEOUT_MS);
111	}
