116	  const have = await exec(conn, `systemctl status ${shellQuote(svc)} >/dev/null 2>&1 && echo yes || echo no`, QUICK_TIMEOUT_MS);
117	  if (have.stdout.trim() === "yes") return;
118	  const prefix = await pkgInstallPrefix(conn);
119	  // php{ver}-fpm + the common extensions apps need.
120	  const inst = await exec(
121	    conn,
122	    `${prefix} php${phpVersion}-fpm php${phpVersion}-mysql php${phpVersion}-cli php${phpVersion}-curl php${phpVersion}-gd php${phpVersion}-mbstring php${phpVersion}-xml`,
123	    INSTALL_TIMEOUT_MS
124	  );
125	  if (inst.code !== 0) throw new Error(`php-fpm install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
126	  await exec(conn, `systemctl enable --now ${shellQuote(svc)}`, SETUP_TIMEOUT_MS);
