129	/**
130	 * Reload nginx, and confirm it is actually running afterwards.
131	 *
132	 * `nginx -t` was already checked; the RELOAD's exit code was discarded (M7 #4),
133	 * so a reload that failed — or a restart that left the daemon dead — read as a
134	 * successful configuration change. A dead nginx takes down every OTHER site on
135	 * the box too, which is why this is checked rather than hoped for.
136	 */
137	export async function reloadNginx(conn: import("ssh2").Client): Promise<void> {
138	  const test = await exec(conn, "nginx -t", SETUP_TIMEOUT_MS);
139	  if (test.code !== 0) throw new Error(`nginx config test failed: ${(test.stderr || test.stdout).trim().slice(0, 200)}`);
140	  const r = await exec(conn, "systemctl reload nginx || systemctl restart nginx", SETUP_TIMEOUT_MS);
141	  const active = await exec(conn, "systemctl is-active nginx 2>/dev/null", QUICK_TIMEOUT_MS);
142	  const state = active.stdout.trim();
143	  if (state !== "active") {
144	    throw new Error(
145	      `nginx is "${state || "not running"}" after the reload (systemctl exited ${r.code}), so no site on this ` +
146	        `server is being served. Diagnose with: systemctl status nginx ; journalctl -u nginx -n 50`
147	    );
148	  }
149	}
