153	export async function websiteCreate(job: Job): Promise<void> {
154	  const site = await loadSite(job);
155	  let proof = "not verified";
156	  try {
157	    // Simulation is a SANDBOX affordance and MUST NEVER run in production.
158	    // Copied from the guard at the end of `sslIssue` in worker/ssl.ts, which
159	    // this file's header claims to mirror and did not. Without it, a production
160	    // box that lost ENABLE_REAL_CPANEL writes ACTIVE and tells the customer
161	    // "Your nginx site is configured and serving" having touched nothing — and
162	    // that ACTIVE is what `requestWebsiteSsl` gates on, so certbot HTTP-01 would
163	    // then be offered for a vhost that does not exist.
164	    if (!REAL && !SANDBOX) {
165	      throw new Error(
166	        "Website provisioning is switched off on this server (ENABLE_REAL_CPANEL is not set), so no nginx " +
167	          "vhost, document root or index page was created on your VM. Nothing is being served — this site " +
168	          "is NOT live. Ask support to enable real control-panel provisioning."
169	      );
170	    }
171	
172	    if (REAL) {
173	      assertDomain(site.domain);
174	      assertPath(site.docRoot);
175	      if (site.phpVersion) assertPhp(site.phpVersion);
176	      const server = await sshServer(site.serverId);
177	      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
178	      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
179	      await withServerSsh(server, async (conn) => {
180	        await ensureNginx(conn);
181	        if (site.phpVersion) await ensurePhpFpm(conn, site.phpVersion);
182	        // Docroot + a friendly placeholder index.
183	        await exec(conn, `mkdir -p ${shellQuote(site.docRoot)} && chown -R www-data:www-data ${shellQuote(site.docRoot)} 2>/dev/null || true`, SETUP_TIMEOUT_MS);
184	        await execInput(
185	          conn,
186	          `cat > ${shellQuote(site.docRoot + "/index.html")}`,
187	          `<!doctype html><meta charset="utf-8"><title>${site.domain}</title><h1>${site.domain}</h1><p>Your Nxeon-hosted site is live.</p>\n`,
188	          SETUP_TIMEOUT_MS
189	        );
190	        // Write the vhost via STDIN (never as an argv token), enable, reload.
191	        await execInput(conn, `cat > ${shellQuote(conf)}`, nginxVhost(site.domain, site.docRoot, site.phpVersion), SETUP_TIMEOUT_MS);
192	        if (site.enabled) {
193	          await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
194	        }
195	        await reloadNginx(conn);
196	
197	        // PROVE it serves. "The job threw no exception" is not evidence, and
198	        // ACTIVE is load-bearing: lib/actions-websites.ts gates the SSL request
199	        // on it, so an unverified ACTIVE offers certbot HTTP-01 for a vhost that
200	        // may be answering 502 or not matching at all. A disabled site is not
201	        // linked into sites-enabled, so there is nothing to probe and we do not
202	        // pretend to have probed it.
203	        if (site.enabled) {
204	          // Deliberately NOT asserting the placeholder's content: the customer
205	          // may already have an index.php, and failing a working site because it
206	          // does not contain our filler text would be its own false report. What
207	          // is claimed is what is proved — this vhost answers for this Host
208	          // header, which is precisely the condition HTTP-01 needs. A 403/404
209	          // still proves nginx routed the request to this server block; a 502 or
210	          // a dead connection does not.
211	          proof = await verifyServing(conn, site.domain, [
212	            {
213	              path: "/",
214	              codes: ["200", "301", "302", "304", "403", "404"],
215	              require: [],
216	              reject: [/502 Bad Gateway/i, /504 Gateway Time-?out/i],
217	              proves: `nginx answers for ${site.domain}`,
218	            },
219	          ]);
220	        }
221	      });
222	    }
223	    await db.website.update({ where: { id: site.id }, data: { status: "ACTIVE", error: null } });
224	    await notify(
225	      site.userId,
226	      `Website ${site.domain} is live`,
227	      REAL
228	        ? site.enabled
229	          ? `Your nginx site is configured and serving — ${proof}.`
230	          : "Your nginx site is configured. It is currently disabled, so nothing is being served yet — enable it to go live."
231	        : "Simulated only (sandbox) — no VM was contacted and nothing is being served.",
232	      `/dashboard/servers/${site.serverId}?tab=control panel`
233	    );
234	  } catch (e: any) {
235	    const reason = String(e?.message ?? e).slice(0, 400);
236	    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: reason } });
237	    await notify(site.userId, `Website ${site.domain} failed`, reason.slice(0, 200), `/dashboard/servers/${site.serverId}`);
238	  }
239	}
