149	export async function dbCreate(job: Job): Promise<void> {
150	  const row = await loadDb(job);
151	  try {
152	    // Validate again before anything can reach a shell/SQL.
153	    assert(row.engine === "mysql" || row.engine === "postgres", `Unsupported engine: ${row.engine}`);
154	    assertIdent(row.name, "database name");
155	    assertIdent(row.dbUser, "database user");
156	
157	    // Simulation is a SANDBOX affordance and MUST NEVER run in production.
158	    // Copied from the guard at the end of `sslIssue` in worker/ssl.ts. Without
159	    // it, a production box that lost ENABLE_REAL_CPANEL flips the row to ACTIVE,
160	    // scrubs the password and tells the customer their database is ready —
161	    // having done nothing at all. `ENABLE_REAL_CPANEL=1` today, so this is
162	    // dormant; one lost .env line is all it takes.
163	    if (!REAL && !SANDBOX) {
164	      throw new Error(
165	        "Database provisioning is switched off on this server (ENABLE_REAL_CPANEL is not set), so no " +
166	          "database, user or password was created on your VM. Nothing exists — this database is NOT ready. " +
167	          "Ask support to enable real control-panel provisioning."
168	      );
169	    }
170	
171	    if (REAL) {
172	      const password = decryptSecret(row.passwordEnc);
173	      assert(password, "Generated password is missing or could not be decrypted.");
174	      assertInertSecret(password, "database password");
175	      const server = await sshServer(row.serverId);
176	      await withServerSsh(server, async (conn) => {
177	        if (row.engine === "mysql") {
178	          await ensureMysql(conn);
179	          // Root socket auth (Debian/Ubuntu default). Password only in the SQL
180	          // body, streamed via STDIN — never an argv token.
181	          const sql =
182	            `CREATE DATABASE IF NOT EXISTS \`${row.name}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\n` +
183	            `CREATE USER IF NOT EXISTS '${row.dbUser}'@'localhost' IDENTIFIED BY '${password}';\n` +
184	            `ALTER USER '${row.dbUser}'@'localhost' IDENTIFIED BY '${password}';\n` +
185	            `GRANT ALL PRIVILEGES ON \`${row.name}\`.* TO '${row.dbUser}'@'localhost';\n` +
186	            `FLUSH PRIVILEGES;\n`;
187	          const r = await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
188	          if (r.code !== 0) throw new Error(`MySQL create failed: ${why(r)}`);
189	          // The credential is about to become unrecoverable (passwordEnc is
190	          // nulled below), so prove it works while we still hold it.
191	          await proveMysqlLogin(conn, row.name, row.dbUser, password!);
192	        } else {
193	          await ensurePostgres(conn);
194	          // Run as the postgres superuser. Role password only in the SQL body via STDIN.
195	          const sql =
196	            `CREATE ROLE "${row.dbUser}" LOGIN PASSWORD '${password}';\n` +
197	            `CREATE DATABASE "${row.name}" OWNER "${row.dbUser}";\n` +
198	            `GRANT ALL PRIVILEGES ON DATABASE "${row.name}" TO "${row.dbUser}";\n`;
199	          const r = await execInput(conn, "sudo -u postgres psql -v ON_ERROR_STOP=1", sql, SETUP_TIMEOUT_MS);
200	          if (r.code !== 0) throw new Error(`PostgreSQL create failed: ${why(r)}`);
201	          await provePostgresLogin(conn, row.name, row.dbUser, password!);
202	        }
203	      });
204	    }
205	    // Scrub the transient secret regardless of path.
206	    await db.vpsDatabase.update({ where: { id: row.id }, data: { status: "ACTIVE", error: null, passwordEnc: null } });
207	    await notify(
208	      row.userId,
209	      `Database "${row.name}" is ready`,
210	      REAL
211	        ? `Your ${row.engine} database and user are provisioned, and we signed in with the generated password to confirm it works.`
212	        : `Simulated only (sandbox) — no VM was contacted and no database exists.`,
213	      `/dashboard/servers/${row.serverId}?tab=control panel`
214	    );
215	  } catch (e: any) {
216	    const reason = String(e?.message ?? e).slice(0, 400);
217	    // Even on failure, do not keep the secret around.
218	    await db.vpsDatabase.update({ where: { id: row.id }, data: { status: "FAILED", error: reason, passwordEnc: null } });
219	    await notify(row.userId, `Database "${row.name}" failed`, reason.slice(0, 200), `/dashboard/servers/${row.serverId}`);
220	  }
221	}
