233	          const sql =
234	            `DROP DATABASE IF EXISTS \`${row.name}\`;\n` +
235	            `DROP USER IF EXISTS '${row.dbUser}'@'localhost';\n` +
236	            `FLUSH PRIVILEGES;\n`;
237	          await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
238	        } else {
239	          const sql =
240	            `DROP DATABASE IF EXISTS "${row.name}";\n` +
241	            `DROP ROLE IF EXISTS "${row.dbUser}";\n`;
