366	/** Update `key value` (whitespace-separated) lines in place; append missing keys. */
367	function updateConvars(content: string, updates: Record<string, string>): string {
368	  const lines = content.split(/\r?\n/);
369	  const seen = new Set<string>();
370	  for (let i = 0; i < lines.length; i++) {
371	    const t = lines[i].trim();
372	    if (!t || t.startsWith("//") || t.startsWith("#")) continue;
373	    const sp = t.search(/\s/);
374	    const key = sp < 0 ? t : t.slice(0, sp);
375	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
376	      lines[i] = `${key} ${updates[key]}`;
377	      seen.add(key);
378	    }
379	  }
380	  for (const k of Object.keys(updates)) {
381	    if (!seen.has(k)) lines.push(`${k} ${updates[k]}`);
382	  }
383	  return lines.join("\n");
384	}
