447	async function tryMinecraftRcon(conn: Client, props: string, v: Values, notes: string[]): Promise<void> {
448	  const kv = parseKeyValue(props);
449	  const enabled = kv["enable-rcon"] === "true";
450	  const password = kv["rcon.password"] ?? "";
451	  const port = kv["rcon.port"] || "25575";
452	  if (!enabled || !password) {
453	    notes.push("RCON is not enabled — restart the server to apply the new settings live.");
454	    return;
455	  }
456	  const which = await execRemote(conn, "command -v mcrcon || true");
457	  if (!which.stdout.trim()) {
458	    notes.push("RCON is enabled but `mcrcon` is not installed — restart to apply live.");
459	    return;
460	  }
461	
462	  // A conservative set of safe live commands. TODO(rcon): expand once the exact
463	  // runtime command set is verified for the target Minecraft build.
464	  const cmds: string[] = [];
465	  if (v["difficulty"] != null) cmds.push(`difficulty ${String(v["difficulty"])}`);
466	  if (v["white-list"] != null) cmds.push(`whitelist ${bool(v["white-list"]) === "true" ? "on" : "off"}`);
467	  if (v["pvp"] != null || v["max-players"] != null || v["motd"] != null) cmds.push("reload");
