469	
470	  const quoted = cmds.map((c) => `'${shq(c)}'`).join(" ");
471	  const res = await execRemote(
472	    conn,
473	    `mcrcon -H 127.0.0.1 -P ${shq(port)} -p '${shq(password)}' ${quoted} 2>&1 || true`
474	  );
475	  notes.push(res.code === 0 ? "Pushed live settings via RCON." : "RCON push attempted (some settings may need a restart).");
476	}
