204	/** Compressed sandbox timeline (real transfers take 5-7 days — see SANDBOX_* notes). */
205	const SANDBOX_APPROVAL_MS = 2 * 60_000;
206	const SANDBOX_REGISTRY_MS = 5 * 60_000;
