473	export async function listRecords(domain: string): Promise<DnsRecord[]> {
474	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}/records`);
475	  return (json.records ?? []).map((r: any) => ({
476	    id: r.id,
477	    host: r.host ?? "",
478	    type: r.type,
479	    answer: r.answer,
480	    ttl: r.ttl ?? 300,
481	    priority: r.priority,
482	  }));
483	}
