502	/** Read-only view used by the DNS UI: apex host shown as "@". */
503	export type DnsHost = { name: string; type: string; address: string; ttl: number; mxPref?: number };
504	
505	export async function getDnsHosts(domain: string): Promise<DnsHost[]> {
506	  const recs = await listRecords(domain);
507	  return recs.map((r) => ({
508	    name: r.host === "" ? "@" : r.host,
509	    type: r.type,
510	    address: r.answer,
511	    ttl: r.ttl,
512	    mxPref: r.priority,
513	  }));
514	}
