/**
 * What `tlsProbeCommand` observed. Every field is something we SAW, never
 * something we inferred from an exit code.
 */
export type TlsProbe = {
  /** HTTP status from `https://<domain>/`. "000" = the request never completed. */
  httpsCode: string;
  /** curl's exit code for that request. 60 = the certificate was not trusted. */
  httpsRc: number;
  /** HTTP status from `http://<domain>/` WITHOUT following redirects. */
  httpCode: string;
  /** Where that plain-HTTP request would have been redirected to ("" = nowhere). */
  redirectTo: string;
  /** `systemctl is-active nginx` AFTER certbot rewrote the configuration. */
  nginxState: string;
  /** No END marker means the script did not finish and we know nothing. */
  complete: boolean;
};

