 *
 *  - NO `-k`. `certbot --nginx` exiting 0 is not evidence that a browser will
 *    accept what nginx now serves, and a probe that disables verification cannot
 *    tell the difference. curl exit 60 here IS the customer's browser warning.
 *  - NO `-L` on the plain-HTTP request. We claim "HTTP redirects to HTTPS", so
 *    the redirect itself is the thing under test; following it would hide its
 *    absence behind a 200 served over port 80.
 *  - It reads `systemctl is-active nginx` back. certbot --nginx REWRITES the
 *    customer's nginx configuration, and a dead nginx takes down every OTHER
 *    site on that box too.
 *
 * Pinned to 127.0.0.1 like `httpProbeCommand`, so it is correct before the
 * customer's DNS has propagated. Pure: covered by `sh -n`/`dash -n` in
 * test/ssl-verify.test.ts.
 */
export function tlsProbeCommand(domain: string): string {
  assertDomain(domain);
  const https = shellQuote(`https://${domain}/`);
  const http = shellQuote(`http://${domain}/`);
  const r443 = shellQuote(`${domain}:443:127.0.0.1`);
  const r80 = shellQuote(`${domain}:80:127.0.0.1`);
  return [
    `say() { printf 'NXTLS:%s\\n' "$1"; }`,
    // 1. The trust-checking request. No -k: a certificate a browser rejects must
    //    fail here, because that is exactly what the customer would see.
    `c=$(curl -sS -o /dev/null --max-time 20 --resolve ${r443} -w '%{http_code}' ${https} 2>/dev/null); rc=$?`,
    `say "HTTPS_CODE:${"$"}{c:-000}"`,
    `say "HTTPS_RC:$rc"`,
    // 2. The redirect claim, tested without following it.
    `h=$(curl -sS -o /dev/null --max-time 20 --resolve ${r80} -w '%{http_code} %{redirect_url}' ${http} 2>/dev/null)`,
    `say "HTTP:${"$"}{h:-000}"`,
    // 3. certbot just rewrote this file. Is the daemon still up?
    `n=$(systemctl is-active nginx 2>/dev/null); say "NGINX:${"$"}{n:-unknown}"`,
    `say "END"`,
  ].join("\n");
}

/** Parse `tlsProbeCommand` output. Pure. */
export function parseTlsProbe(out: string): TlsProbe {
  const text = String(out ?? "");
  const one = (re: RegExp): string => re.exec(text)?.[1]?.trim() ?? "";
  const httpLine = one(/^NXTLS:HTTP:(.*)$/m);
  const [httpCode = "", redirectTo = ""] = httpLine.split(/\s+/);
  const rcRaw = one(/^NXTLS:HTTPS_RC:(-?\d+)$/m);
  return {
    httpsCode: one(/^NXTLS:HTTPS_CODE:(\d{3})$/m) || "000",
    httpsRc: rcRaw === "" ? -1 : Number(rcRaw),
    httpCode: /^\d{3}$/.test(httpCode) ? httpCode : "000",
    redirectTo,
    nginxState: one(/^NXTLS:NGINX:(.*)$/m) || "unknown",
    complete: /^NXTLS:END$/m.test(text),
  };
}

/** Run `tlsProbeCommand` on the VM and parse it. */
export async function probeTls(conn: Client, domain: string): Promise<TlsProbe> {
  const r = await exec(conn, tlsProbeCommand(domain), SETUP_TIMEOUT_MS);
  return parseTlsProbe(String(r.stdout ?? ""));
}

// ---------------------------------------------------------------------------
// "SSL enabled for this website" — the claim worker/websites.ts makes
// ---------------------------------------------------------------------------

/**
 * Everything `websiteSslVerdict` is allowed to reason from. Structurally
 * compatible with `TlsProbe` in lib/http-probe.ts (kept as a separate shape so
 * this module stays free of ssh2 and remains importable by a test).
 */
export type WebsiteSslFacts = {
  /** `classifyCertbotOutcome(...).kind` for the `certbot --nginx` run. */
  certbot: CertbotOutcome["kind"];
  /** HTTP status from https://<domain>/ probed WITHOUT -k. "000" = no answer. */
  httpsCode: string;
  /** curl's exit code for that request. 60/51/91 = the chain was not trusted. */
  httpsRc: number;
  /** HTTP status from http://<domain>/ with redirects NOT followed. */
  httpCode: string;
  /** Where the plain-HTTP request would have gone ("" = nowhere). */
  redirectTo: string;
  /** `systemctl is-active nginx` after certbot rewrote the config. */
  nginxState: string;
  /** Did the probe script finish? */
  complete: boolean;
};

export type WebsiteSslVerdict =
  | { ok: true; note: string; redirects: boolean }
  | { ok: false; reason: string };

/**
 * Decide what `certbot --nginx` plus a read-back are allowed to tell the
 * customer about HTTPS on their site.
 *
 * INCIDENT: `websiteSsl` in worker/websites.ts accepted
 *
 *     run.code === 0 && /Congratulations|Successfully|not yet due for renewal|Deploying certificate/i
 *
 * as proof, wrote `ssl: true`, and sent *"A Let's Encrypt certificate is
 * installed and HTTP redirects to HTTPS."* That is the SAME alternation M7 #6
 * removed from `classifyCertbotOutcome` — "not yet due for renewal" is what
 * certbot prints when it does NOTHING — and it had grown a second head:
 * `/Successfully/i` matches almost any certbot chatter. Nothing was ever read
 * back, so the message was sent for a site whose nginx certbot had just broken,
 * whose 443 nothing was listening on, and whose HTTP did not redirect anywhere.
 *
 * Ordered by what the customer loses, hardest first:
 *  1. nginx down  — EVERY site on that VM is dark, not just this one.
 *  2. TLS untrusted or absent — every visitor gets a full-page browser warning.
 *  3. certbot failed outright.
 * The redirect is reported, never assumed: `--redirect` is requested, but a
 * pre-existing `location /` can beat certbot's rewrite, and claiming a redirect
 * that is not there sends customers hunting for a mixed-content bug they do not
 * have.
 */
export function websiteSslVerdict(domain: string, f: WebsiteSslFacts): WebsiteSslVerdict {
  if (f.certbot === "failed") {
    return {
      ok: false,
      reason:
        `certbot did not obtain or install a certificate for ${domain}, so HTTPS is NOT enabled and nothing ` +
        `about your site changed. The usual causes are that ${domain} does not yet point at this server in ` +
        `DNS, or that port 80 is not reachable from the internet for the HTTP-01 challenge.`,
    };
  }

  if (!f.complete) {
    return {
      ok: false,
      reason:
        `certbot ran for ${domain} but the verification step did not complete, so we cannot confirm HTTPS ` +
        `works and are not claiming that it does. Check the site in a browser and re-run this if it is fine.`,
    };
  }

  // 1. certbot --nginx REWRITES nginx.conf and the vhost. If the daemon did not
  //    survive that, every site on this VM is down — say so before anything else.
  if (f.nginxState !== "active") {
    return {
      ok: false,
      reason:
        `certbot rewrote your nginx configuration for ${domain} and nginx is now "${f.nginxState}" — so NO ` +
        `site on this server is being served, not just this one. Diagnose immediately with: nginx -t ; ` +
        `systemctl status nginx ; journalctl -u nginx -n 50`,
    };
  }

  // 2. Trust. The probe deliberately does not pass -k, so this is what a browser
  //    would do. An exit code from certbot cannot substitute for it.
  if (CERT_UNTRUSTED_RCS.includes(f.httpsRc)) {
    return {
      ok: false,
      reason:
        `https://${domain} is answering, but the certificate it serves is not trusted (curl error ${f.httpsRc}), ` +
        `so every visitor still gets a full-page security warning. HTTPS is not enabled. Check that nginx is ` +
        `serving fullchain.pem rather than cert.pem.`,
    };
  }
  if (f.httpsCode === "000") {
    return {
      ok: false,
      reason:
        `nothing answered on https://${domain} after certbot ran (curl exit ${f.httpsRc}), so HTTPS is NOT ` +
        `enabled — the certificate may exist without nginx listening on 443. Check: ss -ltnp | grep :443 ; ` +
        `nginx -T | grep -A5 "server_name ${domain}"`,
    };
  }

  // A 5xx over TLS means the app is broken, but TLS itself demonstrably works —
  // that is a different problem from the one this job is about, so it is
  // reported rather than used to deny the certificate.
  const appNote =
    /^5\d\d$/.test(f.httpsCode)
      ? ` Note: https://${domain} currently returns HTTP ${f.httpsCode}, so your site itself is erroring — ` +
        `that is an application problem, not a certificate one.`
      : "";

  const redirects = /^30[1278]$/.test(f.httpCode) && /^https:\/\//i.test(f.redirectTo);
  const redirectNote = redirects
    ? `Plain http:// requests redirect to https:// (HTTP ${f.httpCode}).`
    : `Plain http:// requests do NOT redirect to https:// yet (http:// answered ${f.httpCode}` +
      `${f.redirectTo ? ` → ${f.redirectTo}` : ""}), so visitors can still reach the insecure version.`;

  const gotCert =
    f.certbot === "issued"
      ? `A Let's Encrypt certificate was issued and installed for ${domain}.`
      : `certbot reported the existing certificate for ${domain} is not yet due for renewal, so it reused ` +
        `that one rather than requesting a new one — nothing was re-issued.`;

  return {
    ok: true,
    redirects,
    note:
      `${gotCert} We then fetched https://${domain} from the server with certificate verification ON: it ` +
      `answered HTTP ${f.httpsCode} over a trusted chain, and nginx is active. ${redirectNote}${appNote}`,
  };
}

