// ---------------------------------------------------------------------------
// Let's Encrypt rate-limit accounting
// ---------------------------------------------------------------------------

/**
 * `Job.step` values written by worker/ssl.ts. Duplicated there (and in
 * lib/actions-ssl.ts) because neither can import the other; the strings are the
 * contract.
 */
export const STEP_PREFLIGHT_FAILED = "failed before contacting Let's Encrypt";
export const STEP_SANDBOX = "simulated (sandbox)";

/** One SSL_ISSUE Job row, as the counter needs to see it. */
export type IssueJobRow = {
  domain: string;
  /** `Job.attempts` — the worker INCREMENTS this and re-runs the SAME row. */
  attempts: number;
  /** `Job.step` — only ever records the outcome of the LAST attempt. */
  step: string | null;
  createdAt: Date;
};

export type IssueTally = {
  /** Executions of any kind, including ones that never reached the ACME server. */
  total: number;
  /** Executions that may have consumed a Let's Encrypt duplicate-certificate slot. */
  leRelevant: number;
  lastAt: Date;
};

/**
 * Count issue attempts per hostname inside the rate-limit window.
 *
 * THE BUG THIS EXISTS TO FIX: the counter used to be `+1 per Job row`. But
 * worker/index.ts does not create a new row to retry — it flips the SAME row
 * back to QUEUED and increments `attempts` (`MAX_ATTEMPTS = 3`), and
 * `reapStuckJobs` does the same to any job that was RUNNING when the worker
 * restarted. A deploy restarts nxeon-worker, and `certbot certonly` takes tens
 * of seconds, so this is a live path, not a theoretical one.
 *
 * One row could therefore drive THREE real certbot invocations while the counter
 * scored it as one. With the cap set at 4 rows, a hostname could reach twelve
 * ACME requests in a week against Let's Encrypt's limit of 5 duplicate
 * certificates — the precise outcome the cap exists to prevent, and it costs the
 * customer HTTPS for a full week.
 *
 * So we count EXECUTIONS, not rows. And for a row with more than one execution
 * we count every one of them as rate-limit-relevant: `step` records only the
 * final attempt's outcome, so a row that reached ACME on attempt 1 and died in
 * pre-flight on attempt 2 reads as "never reached Let's Encrypt". When in doubt,
 * protect the limit — the same rule `attemptCountsAgainstLimit` already applies
 * to a null step.
 *
 * Pure: no database, no clock. Covered by test/ssl-verify.test.ts.
 */
export function tallyIssueAttempts(jobs: readonly IssueJobRow[]): Map<string, IssueTally> {
  const map = new Map<string, IssueTally>();
  for (const j of jobs) {
    if (!j.domain) continue; // pre-2026-07-26 rows carried only certId
    // `attempts` is incremented when a job is CLAIMED, so a queued-but-never-run
    // row reads 0. It is still an intent to contact Let's Encrypt, and treating
    // it as zero would let a burst of queued rows slip under the cap.
    const runs = Math.max(1, Number.isFinite(j.attempts) ? Math.trunc(j.attempts) : 1);
    // A single execution can be excused from the LE count by its own step. Two
    // or more cannot: we only know how the LAST one ended.
    const excused = runs === 1 && (j.step === STEP_PREFLIGHT_FAILED || j.step === STEP_SANDBOX);
    const prev = map.get(j.domain);
    map.set(j.domain, {
      total: (prev?.total ?? 0) + runs,
      leRelevant: (prev?.leRelevant ?? 0) + (excused ? 0 : runs),
      lastAt: prev && prev.lastAt > j.createdAt ? prev.lastAt : j.createdAt,
