type Attempt = IssueTally;

/**
 * Issue attempts in the current window, keyed by DOMAIN — not by certificate id.
 *
 * The key matters: Let's Encrypt's duplicate-certificate limit is per identical
 * hostname set, and deleting a row and requesting it again mints a fresh certId.
 * A per-certId counter would therefore reset on every delete/re-request, letting
 * a frustrated customer burn all five weekly slots in minutes and lose HTTPS for
 * a week.
 *
 * `Job.attempts` is selected because a retry REUSES the row rather than creating
 * a new one — see `tallyIssueAttempts`, which is where that arithmetic lives and
 * is tested. Counting rows instead of executions was worth up to 3x the real
 * number of ACME requests.
 */
async function loadIssueHistory(): Promise<Map<string, Attempt>> {
  const since = new Date(Date.now() - ISSUE_WINDOW_MS);
  const jobs = await db.job.findMany({
