    select: { payload: true, step: true, createdAt: true, attempts: true },
    orderBy: { createdAt: "asc" },
  });
  return tallyIssueAttempts(
    jobs.map((j) => ({
      domain: payloadOf(j).domain ?? "",
      attempts: j.attempts,
      step: j.step,
      createdAt: j.createdAt,
