input.new_string:
/**
 * Drop the database and its user, and PROVE both are gone before the row is
 * deleted from our side.
 *
 * What this used to do: `await execInput(...)` — with the result DISCARDED, no
 * exit code checked, nothing read back — and then `db.vpsDatabase.delete()`
 * unconditionally. So when the DROP did not run (engine stopped, socket auth
 * broken, `sudo -u postgres` unavailable, the role still owning objects — which
 * makes `DROP ROLE` fail even with IF EXISTS) the panel reported the database
 * deleted while it and its GRANT ALL user were still live on the customer's VM,
 * now invisible and unmanageable. And because `@@unique([serverId, engine, name])`
 * frees the name, the next database created with the same name would be adopted
 * by `CREATE DATABASE IF NOT EXISTS` in `dbCreate` — handing a new, differently
 * scoped credential set onto the OLD data.
 *
 * The read-back is a query, not an exit code: `information_schema` / `pg_database`
 * are asked whether the objects still exist.
 */
export async function dbDelete(job: Job): Promise<void> {
  const row = await loadDb(job);
  try {
    assert(row.engine === "mysql" || row.engine === "postgres", `Unsupported engine: ${row.engine}`);
    assertIdent(row.name, "database name");
    assertIdent(row.dbUser, "database user");
    if (REAL) {
      const server = await sshServer(row.serverId);
      await withServerSsh(server, async (conn) => {
        if (row.engine === "mysql") {
          const sql =
            `DROP DATABASE IF EXISTS \`${row.name}\`;\n` +
            `DROP USER IF EXISTS '${row.dbUser}'@'localhost';\n` +
            `FLUSH PRIVILEGES;\n`;
          const r = await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
          if (r.code !== 0) throw new Error(`MySQL drop failed, so nothing was removed: ${why(r)}`);
          const check = await execInput(
            conn,
            "mysql --protocol=socket -uroot -N -B",
            `SELECT COUNT(*) FROM information_schema.schemata WHERE schema_name = '${row.name}';\n` +
              `SELECT COUNT(*) FROM mysql.user WHERE user = '${row.dbUser}';\n`,
            SETUP_TIMEOUT_MS
          );
          assertDropped(row.engine, row.name, row.dbUser, check.code, check.stdout);
        } else {
          const sql =
            `DROP DATABASE IF EXISTS "${row.name}";\n` +
            `DROP ROLE IF EXISTS "${row.dbUser}";\n`;
          const r = await execInput(conn, "sudo -u postgres psql -v ON_ERROR_STOP=1", sql, SETUP_TIMEOUT_MS);
          if (r.code !== 0) throw new Error(`PostgreSQL drop failed, so nothing was removed: ${why(r)}`);
          const check = await execInput(
            conn,
            "sudo -u postgres psql -t -A -v ON_ERROR_STOP=1",
            `SELECT count(*) FROM pg_database WHERE datname = '${row.name}';\n` +
              `SELECT count(*) FROM pg_roles WHERE rolname = '${row.dbUser}';\n`,
            SETUP_TIMEOUT_MS
          );
          assertDropped(row.engine, row.name, row.dbUser, check.code, check.stdout);
        }
      });
    }
    await db.vpsDatabase.delete({ where: { id: row.id } });
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    await db.vpsDatabase
      .update({ where: { id: row.id }, data: { status: "FAILED", error: reason } })
      .catch(() => {});
    await notify(
      row.userId,
      `Database "${row.name}" was NOT removed`,
      reason.slice(0, 200),
      `/dashboard/servers/${row.serverId}?tab=control panel`
    );
    // Failing the job puts this in Job.error and the admin job list. The DROPs
    // are `IF EXISTS`, so a retry is safe and idempotent.
    throw new Error(`database delete not verified: ${reason}`);
  }
}

/**
 * Both count queries must answer 0. Anything else — including output we cannot
 * parse — means we do not know the objects are gone, and "we do not know" is not
 * "deleted".
 */
function assertDropped(
  engine: string,
  name: string,
  user: string,
  code: number | null,
  stdout: string
): void {
  const counts = String(stdout ?? "").trim().split(/\s+/);
  if (code !== 0 || counts.length < 2) {
    throw new Error(
      `could not confirm the ${engine} database "${name}" and user "${user}" were removed from the server ` +
        `(the check query exited ${code ?? "unknown"}). They may still exist — nothing has been deleted from ` +
        `your panel, so you can retry.`
    );
  }
  if (counts[0] !== "0") {
    throw new Error(
      `the ${engine} database "${name}" still exists on the server after the DROP, so it has NOT been ` +
        `removed. Nothing has been deleted from your panel.`
    );
  }
  if (counts[1] !== "0") {
    throw new Error(
      `the ${engine} database "${name}" was dropped but its user "${user}" still exists on the server — ` +
        `that account can still sign in, so this is not finished. Nothing has been deleted from your panel.`
    );
  }
}

