    assert.ok(v.ok && /no automatic update source/.test(v.body));
    assert.ok(v.ok && !/latest server update was applied/.test(v.body));
  }
});

/* ------------------------------------------------------------------ *
 * 4. The two things this job did to a healthy server, four times a day
 *
 *    (a) It RESTARTED it. The "do not bounce a healthy game server for an
 *        update that did not happen" rule was written into this module and then
 *        applied only to the steamcmd-failure branch. The two branches where
 *        nothing could possibly have been downloaded — a family with no app id
 *        at all (minecraft, terraria), and steamcmd reporting "already up to
 *        date", which is the COMMON answer — both fell through to
 *        `systemctl restart`. Every connected player was disconnected every 6
 *        hours to change nothing.
 *
 *    (b) It NOTIFIED about it, titled "<game> updated on <host>". steamcmd
 *        prints "Success! App '<id>'" for both "already up to date" and "fully
 *        installed", and one grep matched both, so an unchanged server produced
 *        four "updated" notifications a day. `notifyFailureOnce` exists in
 *        worker/game-update.ts precisely because notifications a customer
 *        learns to ignore are the same as no notifications — the success path
 *        had no equivalent and was making a claim that was not true.
 * ------------------------------------------------------------------ */

test("steamcmd's two success lines are no longer the same outcome", () => {
  const already = [
    "NXGU:UNIT:valheim",
    "NXGU:WAS:active",
    "NXGU:STEAM_RC:0",
    "NXGU:STEAM:CURRENT",
    "NXGU:SKIPPED_RESTART:1",
    "NXGU:STATE:active",
    "NXGU:END",
  ].join("\n");
  const f = parseGameUpdateOutput(already);
  assert.equal(f.steam, "current");
  assert.equal(f.restartRc, null, "nothing was restarted, so there is no restart code");
});

test("a server that is already up to date is not restarted and not announced", () => {
  const v = judgeGameUpdate({
    family: "valheim",
    hostname: HOST,
    facts: facts({ steam: "current", restartRc: null }),
  });
  assert.equal(v.ok, true);
  assert.ok(v.ok && !/\bupdated\b/.test(v.title), "the title must not claim an update that did not happen");
  assert.ok(v.ok && /NOT restarted/.test(v.body));
  assert.ok(v.ok && /no players were disconnected/.test(v.body));
  assert.equal(v.ok && v.notify, false, "four of these a day is noise, not news");
});

test("the script only restarts when a NEW build was downloaded", () => {
  // Guard the shape of the bug: the restart must be gated on the freshness flag
  // that only `Success! App '<id>' fully installed` sets, and the two
  // no-download branches must both leave before reaching it.
  for (const family of GAME_FAMILIES) {
    const s = updateCommand(family);
    const restartAt = s.indexOf("systemctl restart");
    if (!updatesFromSteam(family)) {
      assert.equal(restartAt, -1, `${family}: has no update source, so it must never restart the server`);
      assert.match(s, /say "SKIPPED_RESTART:1"/, `${family}: must say it deliberately skipped the restart`);
      continue;
    }
    assert.ok(restartAt > 0, `${family}: a real update still has to restart the service`);
    const gateAt = s.indexOf(`if [ "$fresh" != "1" ]; then`);
    assert.ok(gateAt > 0 && gateAt < restartAt, `${family}: the freshness gate must precede the restart`);
    assert.match(s, /already up to date/, `${family}: must distinguish "nothing to do" from "installed"`);
  }
});

test("no family can reach a restart without an update having been downloaded", () => {
  // Structural, not textual: everything before the gate is the only code that
  // can set `fresh=1`, and it is only set on the "fully installed" branch.
  for (const family of GAME_FAMILIES.filter(updatesFromSteam)) {
    const s = updateCommand(family);
    const sets = [...s.matchAll(/fresh=1/g)];
    assert.equal(sets.length, 1, `${family}: exactly one place may declare an update fresh`);
    const line = s.split("\n").find((l) => l.includes("fresh=1"))!;
    assert.ok(!/already up to date/.test(line), `${family}: "already up to date" must not set the flag`);
  }
});

