/* ------------------------------------------------------------------ *
 * Let's Encrypt rate-limit accounting
 *
 *   `loadIssueHistory` in worker/ssl.ts counted +1 per SSL_ISSUE **Job row**.
 *   But worker/index.ts does not create a row to retry — `reapStuckJobs` and the
 *   failure path both flip the SAME row back to QUEUED and increment
 *   `attempts` (MAX_ATTEMPTS = 3). A deploy restarts nxeon-worker, and
 *   `certbot certonly` takes tens of seconds, so a job caught mid-run is re-run
 *   from the top — certbot included.
 *
 *   One row was therefore worth up to THREE real ACME requests while scoring 1.
 *   With MAX_LE_ATTEMPTS_PER_WINDOW = 4 that is up to 12 requests against Let's
 *   Encrypt's limit of 5 duplicate certificates per week — the exact lockout the
 *   cap exists to prevent, and it costs the customer HTTPS for seven days.
 * ------------------------------------------------------------------ */

const T0 = new Date(Date.parse("2026-07-20T00:00:00.000Z"));
const T1 = new Date(Date.parse("2026-07-21T00:00:00.000Z"));

function job(over: Partial<IssueJobRow> = {}): IssueJobRow {
  return { domain: "shop.example.com", attempts: 1, step: null, createdAt: T0, ...over };
}

test("a retried job counts as the certbot runs it really performed, not as one row", () => {
  // THE BUG. A single row the worker restarted twice ran certbot three times.
  const t = tallyIssueAttempts([job({ attempts: 3 })]);
  assert.equal(t.get("shop.example.com")!.total, 3);
  assert.equal(t.get("shop.example.com")!.leRelevant, 3, "all three reached Let's Encrypt");
});

test("four retried rows cannot slip twelve requests past a cap of four", () => {
  const rows = [0, 1, 2, 3].map((i) =>
    job({ attempts: 3, createdAt: new Date(T0.getTime() + i * 3600_000) }),
  );
  const t = tallyIssueAttempts(rows).get("shop.example.com")!;
  assert.equal(t.leRelevant, 12);
  assert.ok(t.leRelevant >= 4, "the cap in worker/ssl.ts must now see this and stop");
});

test("a single attempt that never reached Let's Encrypt is still excused", () => {
  // The behaviour that must NOT regress: a customer whose port 80 is occupied
  // must not be locked out for a week by failures Let's Encrypt never saw.
  const t = tallyIssueAttempts([job({ attempts: 1, step: STEP_PREFLIGHT_FAILED })]).get("shop.example.com")!;
  assert.equal(t.total, 1);
  assert.equal(t.leRelevant, 0);
  assert.equal(tallyIssueAttempts([job({ step: STEP_SANDBOX })]).get("shop.example.com")!.leRelevant, 0);
});

test("a RETRIED row is never excused by its last step — we only know how the last one ended", () => {
  // Attempt 1 may have reached the ACME server and attempt 2 died in pre-flight;
  // `step` records only the second. Excusing the row would under-count a real
  // Let's Encrypt request, so when in doubt we protect the limit.
  const t = tallyIssueAttempts([job({ attempts: 2, step: STEP_PREFLIGHT_FAILED })]).get("shop.example.com")!;
  assert.equal(t.total, 2);
  assert.equal(t.leRelevant, 2);
});

test("a queued-but-never-claimed row still counts as one intent", () => {
  // `attempts` is incremented when a job is CLAIMED, so a freshly queued row
  // reads 0. Scoring that as zero would let a burst of queued rows sail under
  // the cap and then all run.
  const t = tallyIssueAttempts([job({ attempts: 0 })]).get("shop.example.com")!;
  assert.equal(t.total, 1);
  assert.equal(t.leRelevant, 1);
});

test("the counter keys on hostname, so deleting and re-requesting cannot reset it", () => {
  // Let's Encrypt's duplicate-certificate limit is per identical hostname set;
  // a per-certId counter reset on every delete/re-request.
  const t = tallyIssueAttempts([
    job({ domain: "a.example.com" }),
    job({ domain: "a.example.com", createdAt: T1 }),
    job({ domain: "b.example.com" }),
  ]);
  assert.equal(t.get("a.example.com")!.total, 2);
  assert.equal(t.get("b.example.com")!.total, 1);
  assert.equal(t.get("a.example.com")!.lastAt.getTime(), T1.getTime(), "backoff keys on the newest");
});

test("rows with no domain in the payload are skipped rather than bucketed under ''", () => {
  assert.equal(tallyIssueAttempts([job({ domain: "" })]).size, 0);
});

/* ------------------------------------------------------------------ *
 * "SSL enabled for this website"
 *
 *   `websiteSsl` in worker/websites.ts accepted
 *     run.code === 0 && /Congratulations|Successfully|not yet due for renewal|Deploying certificate/i
 *   as its ENTIRE evidence, wrote `ssl: true` (the padlock in the panel) and
 *   sent "A Let's Encrypt certificate is installed and HTTP redirects to HTTPS."
 *
 *   That is the same alternation M7 #6 removed from the certonly path — "not yet
 *   due for renewal" is what certbot prints when it does nothing — plus a
 *   `/Successfully/i` that matches most of certbot's chatter. Nothing was read
 *   back, so the sentence went out unchanged when certbot had just broken nginx,
 *   when nothing was listening on 443, and when http:// redirected nowhere.
 * ------------------------------------------------------------------ */

function tls(over: Partial<WebsiteSslFacts> = {}): WebsiteSslFacts {
  return {
    certbot: "issued",
    httpsCode: "200",
    httpsRc: 0,
    httpCode: "301",
    redirectTo: "https://shop.example.com/",
    nginxState: "active",
    complete: true,
    ...over,
  };
}

test("certbot breaking nginx is reported before anything else — every site is down", () => {
  // certbot --nginx REWRITES the customer's configuration. This outranks the
  // certificate itself: it is not one site that is dark, it is all of them.
  const v = websiteSslVerdict("shop.example.com", tls({ nginxState: "failed" }));
  assert.equal(v.ok, false);
  assert.ok(!v.ok && /NO site on this server is being served/.test(v.reason));
  assert.ok(!v.ok && /journalctl -u nginx -n 50/.test(v.reason), "every refusal carries a command");
});

test("a certificate a browser will reject is not 'SSL enabled'", () => {
  // curl exit 60 IS the customer's full-page browser warning. The probe omits
  // -k precisely so this cannot be mistaken for success.
  for (const rc of [60, 51, 91]) {
    const v = websiteSslVerdict("shop.example.com", tls({ httpsRc: rc, httpsCode: "000" }));
    assert.equal(v.ok, false, `curl rc ${rc}`);
    assert.ok(!v.ok && /not trusted/.test(v.reason));
    assert.ok(!v.ok && /fullchain\.pem rather than cert\.pem/.test(v.reason));
  }
});

test("a certificate obtained but never served on 443 is not 'SSL enabled'", () => {
  const v = websiteSslVerdict("shop.example.com", tls({ httpsCode: "000", httpsRc: 7 }));
  assert.equal(v.ok, false);
  assert.ok(!v.ok && /nothing answered on https/.test(v.reason));
  assert.ok(!v.ok && /ss -ltnp \| grep :443/.test(v.reason));
});

test("certbot failing is reported as HTTPS not enabled, with the two real causes", () => {
  const v = websiteSslVerdict("shop.example.com", tls({ certbot: "failed" }));
  assert.equal(v.ok, false);
  assert.ok(!v.ok && /HTTPS is NOT enabled/.test(v.reason));
  assert.ok(!v.ok && /does not yet point at this server in DNS/.test(v.reason));
});

test("a probe that did not finish proves nothing and is not upgraded to success", () => {
  const v = websiteSslVerdict("shop.example.com", tls({ complete: false }));
  assert.equal(v.ok, false);
  assert.ok(!v.ok && /not claiming that it does/.test(v.reason));
});

test("the redirect is REPORTED, never assumed — the old message asserted it flatly", () => {
  const yes = websiteSslVerdict("shop.example.com", tls());
  assert.ok(yes.ok && yes.redirects);
  assert.ok(yes.ok && /redirect to https/.test(yes.note));

  // --redirect was asked for, but a pre-existing `location /` can beat certbot's
  // rewrite. HTTPS still works, so this is a success — with an accurate sentence.
  const no = websiteSslVerdict("shop.example.com", tls({ httpCode: "200", redirectTo: "" }));
  assert.equal(no.ok, true);
  assert.ok(no.ok && !no.redirects);
  assert.ok(no.ok && /do NOT redirect/.test(no.note));
  assert.ok(no.ok && /can still reach the insecure version/.test(no.note));
});

test("'not yet due for renewal' never reads as a certificate having been issued", () => {
  // The M7 #6 string, in the file it was never removed from. HTTPS genuinely
  // works here, so this IS a success — but the sentence must not invent an event.
  const v = websiteSslVerdict("shop.example.com", tls({ certbot: "unchanged" }));
  assert.equal(v.ok, true);
  assert.ok(v.ok && /not yet due for renewal/.test(v.note));
  assert.ok(v.ok && /nothing was re-issued/.test(v.note));
  assert.ok(v.ok && !/was issued and installed/.test(v.note));
});

test("a success states what was verified, including that verification was ON", () => {
  const v = websiteSslVerdict("shop.example.com", tls());
  assert.ok(v.ok && /certificate verification ON/.test(v.note));
  assert.ok(v.ok && /trusted chain/.test(v.note));
});

test("a site erroring over working TLS is a success for TLS and says so plainly", () => {
  // A 502 behind a valid certificate is an application problem. Denying the
  // certificate would be its own false report.
  const v = websiteSslVerdict("shop.example.com", tls({ httpsCode: "502" }));
  assert.equal(v.ok, true);
  assert.ok(v.ok && /application problem, not a certificate one/.test(v.note));
});

/* ------------------------------------------------------------------ *
 * Generated shell
 *   A quoting mistake passes typecheck, lint and build, then fails on a
 *   customer's live server. Same reason test/migration-gate.test.ts parses
 *   srcInventoryScript with sh -n / dash -n.
 * ------------------------------------------------------------------ */

function parses(script: string, label: string) {
  const file = join(tmpdir(), `nxeon-ssl-${label}-${process.pid}.sh`);
  try {
    writeFileSync(file, script, "utf8");
    // -n parses without executing: nothing here touches the machine.
    execFileSync("sh", ["-n", file], { stdio: "pipe" });
    execFileSync("dash", ["-n", file], { stdio: "pipe" });
  } finally {
    rmSync(file, { force: true });
  }
}

test("the TLS and HTTP probe scripts parse under sh -n and dash -n", () => {
  parses(tlsProbeCommand("shop.example.com"), "tls");
  parses(httpProbeCommand("shop.example.com", "/"), "http");
  parses(httpProbeCommand("shop.example.com", "/wp-admin/install.php"), "httppath");
  // Hyphens and digits are legal in hostnames and must survive the quoting.
  parses(tlsProbeCommand("my-shop2.example.co.uk"), "tlshyphen");
});

test("nothing unvalidated can reach the probe shell", () => {
  for (const bad of ["shop.example.com; rm -rf /", "shop.example.com'", "a b.com", "-oProxyCommand=x.com"]) {
    assert.throws(() => tlsProbeCommand(bad), /Unsupported domain/, bad);
    assert.throws(() => httpProbeCommand(bad, "/"), /Unsupported domain/, bad);
  }
  for (const bad of ["/x;rm -rf /", "../../etc/passwd", "/x'y", "no-leading-slash"]) {
    assert.throws(() => httpProbeCommand("shop.example.com", bad), /Unsupported probe path/, bad);
  }
});

test("the TLS probe never disables certificate verification", () => {
  // The whole point. `-k` here would make the probe agree with any certificate,
  // including the self-signed one the customer is complaining about.
  const s = tlsProbeCommand("shop.example.com");
  assert.ok(!/\s-k\b/.test(s), "no -k");
  assert.ok(!/--insecure/.test(s), "no --insecure");
  assert.ok(!/\s-L\b/.test(s), "the redirect is under test, so it must not be followed");
  assert.match(s, /systemctl is-active nginx/, "certbot rewrote nginx; read its state back");
});

test("the probe output parses into exactly what was observed", () => {
  const f = parseTlsProbe(
    [
      "NXTLS:HTTPS_CODE:200",
      "NXTLS:HTTPS_RC:0",
      "NXTLS:HTTP:301 https://shop.example.com/",
      "NXTLS:NGINX:active",
      "NXTLS:END",
    ].join("\n"),
  );
  assert.deepEqual(f, {
    httpsCode: "200",
    httpsRc: 0,
    httpCode: "301",
    redirectTo: "https://shop.example.com/",
    nginxState: "active",
    complete: true,
  });
});

test("an untrusted chain parses as a curl error, not as a missing site", () => {
  const f = parseTlsProbe(
    ["NXTLS:HTTPS_CODE:000", "NXTLS:HTTPS_RC:60", "NXTLS:HTTP:200 ", "NXTLS:NGINX:active", "NXTLS:END"].join("\n"),
  );
  assert.equal(f.httpsRc, 60);
  assert.equal(f.httpsCode, "000");
  assert.equal(f.redirectTo, "", "no redirect target is empty, not the literal string 'undefined'");
  assert.equal(websiteSslVerdict("shop.example.com", { ...tls(), ...f }).ok, false);
});

test("truncated probe output is incomplete, not a blank success", () => {
  const f = parseTlsProbe("NXTLS:HTTPS_CODE:200\nNXTLS:HTTPS_RC:0");
  assert.equal(f.complete, false);
  assert.equal(f.nginxState, "unknown");
  assert.equal(websiteSslVerdict("shop.example.com", { ...tls(), ...f }).ok, false);
});
