/* ------------------------------------------------------------------ *
 * Game settings: the `string` fields are the only unvalidated ones
 *
 *   `validateConfig` constrains `enum` to its option list, `int` to its bounds
 *   and `bool` to a boolean — but `string` accepted any 256 characters,
 *   INCLUDING newlines. Those values are written verbatim into LINE-ORIENTED
 *   config files on the customer's live VM by worker/game-config.ts:
 *
 *     updateKeyValue()  ->  server.properties     `motd=<value>`
 *     updateConvars()   ->  Rust server.cfg       `server.hostname "<value>"`
 *     applyValheim()    ->  launch-args file      `-world "<value>"`
 *
 *   A newline therefore does not set one option, it appends further ones. A motd
 *   of "hi\nenable-rcon=true\nrcon.password=x" turns RCON on with a chosen
 *   password — and worker/game-config.ts then reads rcon.port back out of that
 *   same file and interpolates it into an `mcrcon` command line UNQUOTED
 *   (`-P ${shq(port)}`), so the injected value reaches a shell.
 *
 *   This is the allowlist for the one field type that had none, applied at the
 *   single point the UI, the server action and the worker all validate through.
 * ------------------------------------------------------------------ */

test("a newline in a string setting is refused, not written into server.properties", () => {
  const r = validateConfig("minecraft", { motd: "Welcome\nenable-rcon=true\nrcon.password=hunter2" });
  assert.equal(r.ok, false);
  assert.ok(!r.ok && /line breaks or control characters/.test(r.error));
});

test("every string field on every family rejects control characters", () => {
  // Enumerated from the schema rather than hardcoded, so a new string field
  // added later cannot quietly reopen this.
  let checked = 0;
  for (const family of Object.keys(GAME_CONFIG_SCHEMAS)) {
    const schema = schemaFor(family)!;
    for (const field of schema.fields) {
      if (field.type !== "string") continue;
      checked++;
      for (const bad of ["a\nb", "a\rb", "a�b", "ab", "ab"]) {
        const r = validateConfig(family, { [field.key]: bad });
        assert.equal(r.ok, false, `${family}.${field.key} accepted ${JSON.stringify(bad)}`);
      }
    }
  }
  assert.ok(checked >= 4, `expected several string fields, saw ${checked}`);
});

test("Rust's hostname cannot inject a second convar into server.cfg", () => {
  // updateConvars() writes `server.hostname "<value>"` as one line; a newline
  // would append convars of the attacker's choosing to the file.
  assert.equal(validateConfig("rust", { hostname: 'My Server"\nserver.pve true' }).ok, false);
});

test("Valheim's world name and password cannot inject launch arguments", () => {
  assert.equal(validateConfig("valheim", { world: 'Dedicated"\n-crossplay' }).ok, false);
  assert.equal(validateConfig("valheim", { password: "secret\n-public 1" }).ok, false);
});

test("ordinary punctuation in a server name is still allowed", () => {
  // The rule rejects control characters, not typography — refusing a legitimate
  // MOTD would just push customers to edit the file by hand.
  const r = validateConfig("minecraft", { motd: "Bob's Server — PvP! <ready> §a100% \"fun\"" });
  assert.equal(r.ok, true);
  assert.ok(r.ok && r.values.motd === "Bob's Server — PvP! <ready> §a100% \"fun\"");
});

test("the other field types were already constrained and stay that way", () => {
  // Guards the claim that `string` was the ONLY hole.
  assert.equal(validateConfig("minecraft", { difficulty: "peaceful; rm -rf /" }).ok, false, "enum");
  assert.equal(validateConfig("minecraft", { "max-players": 99999 }).ok, false, "int upper bound");
  assert.equal(validateConfig("minecraft", { "max-players": "12\n" }).ok, true, "int is coerced to a number");
  const n = validateConfig("minecraft", { "max-players": "12\n" });
  assert.equal(n.ok && n.values["max-players"], 12);
  const b = validateConfig("minecraft", { pvp: "false\nx" });
  assert.equal(b.ok && b.values.pvp, false, "bool is coerced to a boolean, never echoed back");
});

test("defaults are shell-inert, so an untouched config can never carry an injection", () => {
  for (const family of Object.keys(GAME_CONFIG_SCHEMAS)) {
    const r = validateConfig(family, {});
    assert.equal(r.ok, true, family);
    for (const [k, v] of Object.entries(r.ok ? r.values : {})) {
      if (typeof v !== "string") continue;
      // eslint-disable-next-line no-control-regex
      assert.ok(!/[\x00-\x1f\x7f]/.test(v), `${family}.${k} default contains a control character`);
    }
  }
});
